// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Cumhuriyet dönemi şiiri: topluluklar ve şairler (kolay).
const ozLiterature8Kolay = <(String, String, List<String>, String)>[
  ('Aşağıdaki sıralamalardan hangisi Cumhuriyet döneminde ortaya çıkan şiir topluluklarını doğru kronolojik sırayla verir?', 'Yedi Meşaleciler → Garip → İkinci Yeni', ['Garip → Yedi Meşaleciler → İkinci Yeni', 'İkinci Yeni → Garip → Yedi Meşaleciler', 'Yedi Meşaleciler → İkinci Yeni → Garip'], 'Yedi Meşale 1928\'de, Garip 1941\'de ortak kitapla ortaya çıkmış, İkinci Yeni ise 1950\'lerin ortasında adlandırılmıştır.'),
  ('Ahmet Kutsi Tecer\'in şiirlerinde halk şiiri geleneğinden yararlanma biçimi en iyi hangi seçenekte özetlenir?', 'Koşma ve türkü yapısını modern bir duyarlılıkla yeniden işlemesi', ['Halk şiirini tümüyle reddedip aruzla yazması', 'Âşık atışmalarını olduğu gibi derleyip yayımlaması', 'Halk ağzını tümden dışlayıp yalnız İstanbul argosunu ve sokak dilini kullanması'], 'Tecer, hece ölçüsü ve koşma-türkü yapısını kullanırken bunları bireysel ve sade bir lirizmle yenilemiştir.'),
  ('Cumhuriyet\'in ilk yıllarında Faruk Nafiz, Kemalettin Kamu ve Ömer Bedrettin Uşaklı gibi şairlerin şiirleri için hangi genelleme en doğrudur?', 'Hece ölçüsüyle Anadolu\'yu, yurt sevgisini ve memleket manzaralarını işlemişlerdir.', ['Ölçü ve kafiyeyi reddederek gündelik dille yazmışlardır.', 'Anlamı kapalı, soyut imgelerle bireyin bunalımını anlatmışlardır.', 'Sınıf çatışmasını merkeze alan ve emekçiyi kahraman yapan toplumcu gerçekçi bir şiir kurmuşlardır.'], 'Bu şairler Millî Edebiyat zevkini Cumhuriyet\'e taşıyarak hece, sade dil ve memleket temalarıyla yazmayı sürdürmüştür.'),
  ('Bir edebiyat dersinde öğretmen, \'Bu şair aruzla değil heceyle yazdı, Anadolu\'yu bir yolculuk boyunca han duvarlarındaki yazılarla anlattı, sonra da Onuncu Yıl Marşı\'na söz yazdı.\' diyor. Sözü edilen şairin hangi toplulukla anıldığı sorulsa doğru yanıt hangisi olur?', 'Beş Hececiler', ['Yedi Meşaleciler', 'Garipçiler', 'Hisarcılar'], 'Anlatılan şair Faruk Nafiz Çamlıbel\'dir; o, Beş Hececiler arasında sayılır.'),
  ('Behçet Kemal Çağlar ile ilgili aşağıdaki yargılardan hangisi doğrudur?', 'Cumhuriyet coşkusunu işleyen şiirleriyle tanınmış, Onuncu Yıl Marşı\'nın söz yazarlarındandır.', ['Garip hareketinin önsözünü kaleme alan şairdir.', 'İkinci Yeni\'ye adını veren yazının yazarıdır.', 'Yedi Meşale ortak kitabında şiirleri bulunan ve Meşale dergisini yöneten şairdir.'], 'Behçet Kemal Çağlar, Atatürk ve Cumhuriyet sevgisini işleyen şiirleriyle bilinir; Faruk Nafiz ile birlikte Onuncu Yıl Marşı\'nı yazmıştır.'),
  ('\'Ne içindeyim zamanın, / Ne de büsbütün dışında\' dizeleriyle zamanın dışına taşan bir anı anlatan şair kimdir?', 'Ahmet Hamdi Tanpınar', ['Ahmet Muhip Dıranas', 'Cahit Sıtkı Tarancı', 'Necip Fazıl Kısakürek'], 'Bu dizeler Tanpınar\'ın \'Ne İçindeyim Zamanın\' şiirindendir; zaman ve rüya onun şiirinin ana temalarıdır.'),
  ('Tanpınar\'ın şiir anlayışı aşağıdakilerden hangisiyle en iyi açıklanır?', 'Musikiye yaklaşan, rüya ve zaman duygusunu öne çıkaran saf bir şiir', ['Gündelik konuşma dilini, espriyi ve sıradan insanı öne çıkaran yalın bir şiir', 'Sloganlarla halkı eyleme çağıran siyasal bir şiir', 'Halk ağzıyla destan anlatan epik bir şiir'], 'Ahmet Haşim ve Valéry çizgisinde duran Tanpınar, şiiri ahenk, rüya ve zaman üzerine kurulu saf bir sanat olarak görmüştür.'),
  ('Ahmet Muhip Dıranas\'ın şiirine en çok hangi Batı akımının etkisi yansımıştır?', 'Sembolizm', ['Fütürizm', 'Natüralizm', 'Dadaizm'], 'Dıranas, Ahmet Haşim\'den gelen sembolist çizgiyi hece ölçüsüyle sürdürmüş; ahenk, telkin ve imgeye önem vermiştir.'),
  ('Ahmet Muhip Dıranas\'ın ölçü konusundaki tutumu için hangisi doğrudur?', 'Hece ölçüsünü büyük bir ahenk ustalığıyla kullanmıştır.', ['Yalnız serbest ölçüyle yazmış, heceye hiç başvurmamıştır.', 'Bütün şiirlerini aruzun tek bir kalıbıyla yazmıştır.', 'Ölçüyü reddederek düzyazı şiirle yetinmiştir.'], 'Dıranas, Fahriye Abla gibi şiirlerinde heceyi akıcı ve musikili biçimde kullanmasıyla öne çıkar.'),
  ('\'Memleket isterim / Gök mavi, dal yeşil, tarla sarı olsun\' dizeleriyle düşlediği yurdu anlatan şair kimdir?', 'Cahit Sıtkı Tarancı', ['Orhan Veli Kanık', 'Faruk Nafiz Çamlıbel', 'Ziya Osman Saba'], 'Dizeler Cahit Sıtkı\'nın \'Memleket İsterim\' şiirindendir; şair huzurlu, kardeşçe bir ülke özlemini sade bir dille anlatır.'),
  ('Cahit Sıtkı Tarancı\'nın şiir dili için hangisi söylenebilir?', 'Ölçü ve kafiyeye bağlı kalarak açık, duru ve özenli bir Türkçe kullanmıştır.', ['Uydurma sözcüklerle ve kırık sözdizimiyle anlamı kasıtlı olarak bulanıklaştırmıştır.', 'Arapça ve Farsça tamlamalarla ağır bir dil kurmuştur.', 'Yalnızca halk ağzı ve yöresel söyleyişle yazmıştır.'], 'Cahit Sıtkı, biçim titizliğini koruyan ve anlaşılır, temiz bir Türkçeyle yazan şairlerdendir.'),
  ('Necip Fazıl\'ın ölçü ve biçim konusundaki tutumu için en doğru yargı hangisidir?', 'Heceyi, sağlam kafiye ve sıkı bir biçim disipliniyle kullanmıştır.', ['Ölçü ve kafiyeyi tamamen bırakıp serbest şiir yazmıştır.', 'Yalnız aruzla, divan nazım biçimlerinde yazmıştır.', 'Şiirlerini ölçüsüz bir düzyazı biçiminde, mensur şiir olarak yayımlamayı tercih etmiştir.'], 'Necip Fazıl hece ölçüsünü ustalıkla kullanmış, kafiyeye ve ahenge büyük önem vermiş, biçimden ödün vermemiştir.'),
  ('Necip Fazıl\'ın şiirlerinde sık görülen \'kaldırım, gece, sokak lambası, yalnız adam\' imgeleri hangi temayı güçlendirir?', 'Büyük şehirde yalnızlık ve iç tedirginlik', ['Kır hayatının huzuru ve bereketi', 'Savaş meydanındaki kahramanlık ve zafer coşkusu', 'Deniz yolculuğunun neşesi'], 'Bu imgeler, ilk dönem şiirlerinde şehrin içinde kaybolan, kendinden ve ölümden korkan insanı anlatır.'),
  ('Nazım Hikmet\'in ilk şiirleri, sonradan benimseyeceği serbest şiirden farklı olarak hangi özelliği taşır?', 'Hece ölçüsüyle ve Hececiler\'in etkisinde yazılmıştır.', ['Anlamı kapalı İkinci Yeni şiiri gibidir.', 'Garip önsözündeki ilkelere göre, ölçüsüz ve kafiyesiz yazılmıştır.', 'Tamamen Fransızca kaleme alınmıştır.'], 'Nazım gençlik şiirlerinde hece ölçüsünü ve Beş Hececiler\'in söyleyişini kullanmış, Moskova yıllarından sonra serbest şiire geçmiştir.'),
  ('\'Başım köpük köpük bulut, içim dışım deniz\' dizesiyle açılan ve şairin kendini Gülhane Parkı\'ndaki bir ağaçla özdeşleştirdiği Nazım Hikmet şiiri hangisidir?', 'Ceviz Ağacı', ['Salkımsöğüt', 'Masalların Masalı', 'Kerem Gibi'], 'Bu dizeler \'Ceviz Ağacı\' şiirinin girişidir; şair kendini İstanbul\'daki budaklı, yapraklı bir ceviz ağacına benzetir.'),
  ('\'Akıyordu su / gösterip aynasında söğüt ağaçlarını\' diye başlayan ve atından düşerek ölen bir süvariyi anlatan Nazım Hikmet şiiri hangisidir?', 'Salkımsöğüt', ['Ceviz Ağacı', 'Kız Çocuğu', 'Masalların Masalı'], 'Salkımsöğüt, akan su ve söğütlerin ortasında ölen bir kızıl süvarinin hikâyesini anlatan erken dönem bir şiiridir.'),
  ('\'Su başında durmuşuz / çınarla ben\' dizesiyle başlayan ve varlıkların birbirine bağlılığını anlatan Nazım Hikmet şiiri hangisidir?', 'Masalların Masalı', ['Ceviz Ağacı', 'Hasret', 'Gece Gelen Telgraf'], 'Masalların Masalı\'nda şair, çınar, kedi ve güneşle birlikte su başında durur; hepsinin gelip geçiciliğini ama yaşamın sevincini anlatır.'),
  ('Nazım Hikmet hangi şehirde ölmüş ve oraya gömülmüştür?', 'Moskova', ['Varşova', 'Sofya', 'Prag'], 'Nazım 3 Haziran 1963\'te Moskova\'da ölmüş ve Novodeviçi Mezarlığı\'na gömülmüştür.'),
  ('Nazım Hikmet\'in Hapiste Yatacak Olana Dair Bazı Öğütler şiirinde mahkûma verdiği temel öğüt nasıl özetlenebilir?', 'Umudu ve dünyaya bağlılığı yitirmeden içerde de yaşamayı sürdürmek', ['Bütün dostlarıyla bağını kesip dış dünyayı unutarak cezasının bitmesini beklemek', 'Kaçış planı yapıp gardiyanları kandırmak', 'Şiir yazmayı bırakıp yalnız uyumak'], 'Şiir, içerdeki insana dışarıyı, sevgiyi ve umudu canlı tutmasını; zamanı boşa harcamadan direnmesini öğütler.'),
  ('Nazım Hikmet\'in açtığı yolda 1940\'larda şiir yazan Rıfat Ilgaz, Enver Gökçe, Arif Damar ve Ahmed Arif gibi şairlerin ortak özelliği hangisidir?', 'Emekçi halkın sorunlarını gerçekçi bir dille işleyen toplumcu bir şiir yazmaları', ['Ölçü ve kafiyeyi korumak için yalnızca aruzla yazan bir anlayışı sürdürmeleri', 'Anlamı kapalı tutan, imgeyi her şeyin üstünde gören ve toplumsal içerikten kaçan soyut bir şiir kurmaları', 'Bireyin ölüm korkusunu ve metafizik bunalımını tek konu olarak seçmeleri'], 'Bu kuşak \'1940 kuşağı toplumcu gerçekçiler\' olarak anılır; yoksulluk, sömürü ve emek konularını gerçekçi bir dille ele almıştır.'),
  ('\'Dost Dost İlle Kavga\' adlı şiir kitabıyla tanınan, 1940 kuşağının toplumcu şairlerinden biri kimdir?', 'Enver Gökçe', ['Rıfat Ilgaz', 'Cahit Külebi', 'Behçet Necatigil'], 'Dost Dost İlle Kavga, Enver Gökçe\'nin en bilinen kitabıdır; halk söyleyişiyle mücadele duygusunu birleştirir.'),
  ('\'Beşikler vermişim Nuh\'a / Salıncaklar, hamaklar\' dizeleriyle Anadolu\'yu konuşturan şair kimdir?', 'Ahmed Arif', ['Fazıl Hüsnü Dağlarca', 'Nazım Hikmet', 'Cahit Külebi'], 'Bu dizeler Ahmed Arif\'in \'Anadolu\' şiirindendir; Anadolu, insanlığa beşiklik eden kadim bir toprak olarak kendi ağzından anlatılır.'),
  ('\'Terketmedi sevdan beni / Aç kaldım, susuz kaldım\' dizeleri hangi şairin cezaevinde yazdığı ve sonradan bestelenen şiirindendir?', 'Ahmed Arif', ['Attila İlhan', 'Sabahattin Ali', 'Can Yücel'], 'Ahmed Arif, cezaevinde geçirdiği yıllarda yazdığı bu şiirde zulme karşın sevdasını ve umudunu yitirmeyen bir sesi dile getirir.'),
  ('Ahmed Arif\'in doğduğu ve şiirlerindeki coğrafyaya yön veren şehir hangisidir?', 'Diyarbakır', ['Erzurum', 'Kars', 'Malatya'], 'Ahmed Arif 1927\'de Diyarbakır\'da doğmuştur; şiirlerinde bölgenin dağları, insanları ve acıları yer alır.'),
  ('\'Haziran\'da Ölmek Zor\' adlı şiir kitabının şairi kimdir?', 'Hasan Hüseyin Korkmazgil', ['Ahmed Arif', 'Ataol Behramoğlu', 'Rıfat Ilgaz'], 'Haziran\'da Ölmek Zor (1970), Hasan Hüseyin Korkmazgil\'in en tanınmış kitaplarındandır.'),
  ('Hasan Hüseyin Korkmazgil\'in şiiri için hangisi en uygun nitelemedir?', 'Anadolu insanının yoksulluğunu halk diliyle anlatan toplumcu bir şiir', ['Saray çevresinin zevkine seslenen aruzlu ve süslü bir şiir', 'Şehirli bireyin bunalımını soyut ve kapalı imgelerle anlatan, halktan kopuk bir şiir', 'Yalnızca doğa güzelliklerini öven, toplumsal içerikten uzak bir şiir'], 'Sivas Gürünlü şair, köylünün ve emekçinin dertlerini halk söyleyişinden beslenen sade bir dille işlemiştir.'),
  ('Garip kitabının önsözünü kaleme alan ve topluluğun görüşlerini kuramsal olarak ortaya koyan şair kimdir?', 'Orhan Veli', ['Melih Cevdet Anday', 'Oktay Rifat Horozcu', 'Ahmet Muhip Dıranas'], 'Garip\'in ünlü önsözü Orhan Veli tarafından yazılmıştır; ölçü, kafiye ve şairaneliğe karşı çıkan görüşler burada dile getirilir.'),
  ('Garip hareketi, kendinden sonra gelen ve \'yeni\' adını taşıyan bir başka şiir anlayışıyla karşılaştırıldığı için edebiyat tarihlerinde hangi adla da anılır?', 'Birinci Yeni', ['Yeni Klasisizm', 'Yeni Lisan', 'Toplumcu Yeni'], '1950\'lerdeki İkinci Yeni adlandırması yapıldığında, ondan önce gelen Garip hareketi de \'Birinci Yeni\' olarak anılmaya başlanmıştır.'),
  ('Garip önsözünde şiirin hitap etmesi gereken zevk konusunda savunulan görüş hangisidir?', 'Şiir, küçük bir seçkin zümrenin değil kalabalığın zevkine seslenmelidir.', ['Şiir yalnızca saray çevresinin ve eğitimli seçkinlerin inceltilmiş zevkine göre yazılmalıdır.', 'Şiir, eski divan şairlerinin beğenisini örnek almalıdır.', 'Şiir yalnız başka şairlerin anlayabileceği kapalı bir dil kurmalıdır.'], 'Orhan Veli önsözde edebiyatın belli bir zümrenin malı olmasına karşı çıkar, şiirin geniş halk kitlesinin zevkine yönelmesini ister.'),
  ('\'Ağlasam sesimi duyar mısınız, / Mısralarımda\' dizeleriyle başlayan ve şairin duygularını sözcüklere dökmenin güçlüğünü anlatan Orhan Veli şiiri hangisidir?', 'Anlatamıyorum', ['Kitabe-i Seng-i Mezar', 'İstanbul\'u Dinliyorum', 'Bedava'], '\'Anlatamıyorum\' şiirinde şair gözyaşlarına dokunabilir mi diye sorar; dilin duyguyu aktarmadaki yetersizliğini dile getirir.'),
  ('\'Gemliğe doğru / Denizi göreceksin\' dizeleriyle başlayan şiirde Orhan Veli okura nasıl bir öğüt verir?', 'Gördüğü güzellik karşısında şaşırmamasını, doğallıkla bakmasını', ['Denize hiç yaklaşmamasını, kıyıdan uzak durup yalnızca uzaktan bakmasını', 'Gemlik\'e gitmeyip İstanbul\'da kalmasını', 'Denizi anlatan eski şiirleri ezberlemesini'], 'Şiir \'Sakın şaşırma\' uyarısıyla devam eder; Orhan Veli büyük bir güzelliği sade ve şakacı bir dille, şaşkınlığa kapılmadan karşılamayı öğütler.'),
  ('Oktay Rifat\'ın şiir dışında da üretken olduğunu gösteren bilgi hangisidir?', 'Romanlar ve tiyatro oyunları da yazmıştır.', ['Yalnızca halk masalı derlemiş, başka eser vermemiştir.', 'Bütün ömrünü resim sanatına adamış, şiiri bırakmıştır.', 'Divan şairleri üzerine sözlükler hazırlamıştır.'], 'Oktay Rifat, Bir Kadının Penceresinden ve Danaburnu gibi romanlar ile çeşitli oyunlar da yazmıştır.'),
  ('Cahit Külebi\'nin şiirini besleyen başlıca kaynak hangisidir?', 'Anadolu insanı, halk türküleri ve kır hayatı', ['Antik Yunan mitolojisi ve felsefesi', 'Fransız sembolistlerinin salon şiiri', 'Divan şiirinin gazel ve kaside geleneği ile saray hayatı'], 'Tokatlı şair, Anadolu\'yu, köy insanını ve türkü söyleyişini lirik, sade bir dille işlemiştir.'),
  ('Asaf Halet Çelebi\'nin şiirlerinde başvurduğu kaynaklar hangi seçenekte en doğru biçimde verilmiştir?', 'Budizm, tasavvuf, Hint ve Bizans gibi Doğu kültürlerinin mistik dünyası', ['Anadolu köylüsünün toprak sorunu ve emekçinin hakları', 'Büyük şehirdeki memurun gündelik hayatı ve esprisi', 'Kurtuluş Savaşı\'nın cephe anıları, kahramanlıkları ve zaferleri'], 'Sidharta, İbrahim, Mariya Bizantina gibi şiirlerinde Asaf Halet, Doğu\'nun mistik geleneklerini ve eski uygarlıkları bir arada kullanır.'),
  ('Ressam kimliğiyle de tanınan ve \'Karadutum, çatal karam, çingenem\' dizesinin yer aldığı şiirin şairi kimdir?', 'Bedri Rahmi Eyüboğlu', ['Ömer Bedrettin Uşaklı', 'Cahit Külebi', 'Ahmet Muhip Dıranas'], 'Karadut, Bedri Rahmi\'nin hem şiirine hem de 1948 tarihli kitabına ad olmuştur; şair halk söyleyişini renkli imgelerle birleştirir.'),
  ('\'Yalnızlık paylaşılmaz, / Paylaşılsa yalnızlık olmaz\' dizeleriyle bilinen ve kısa, özdeyiş gibi şiirleriyle tanınan şair kimdir?', 'Özdemir Asaf', ['Ümit Yaşar Oğuzcan', 'Behçet Necatigil', 'Cemal Süreya'], 'Özdemir Asaf\'ın şiiri, söz oyunlarına ve kısa, düşündürücü özdeyişlere dayanır; bu dizeler onun en bilinenlerindendir.'),
  ('\'Sana gitme demeyeceğim. / Üşüyorsun ceketimi al\' dizeleriyle başlayan Özdemir Asaf şiirinin adı nedir?', 'Lavinia', ['Olvido', 'Mona Roza', 'Fahriye Abla'], 'Lavinia, Özdemir Asaf\'ın en çok bilinen aşk şiiridir. Olvido Dıranas\'ın, Mona Roza Sezai Karakoç\'un, Fahriye Abla Dıranas\'ın şiiridir.'),
  ('Özdemir Asaf\'ın şiir dilini en iyi anlatan nitelik hangisidir?', 'Az sözle çok şey söyleyen, sözcük oyunlarına dayalı özlü bir anlatım', ['Uzun destanlarda olayları ayrıntıyla anlatan epik bir anlatım', 'Divan şiirinin süslü tamlamalarını ve kalıp benzetmelerini yeniden canlandıran ağır bir dil', 'Halk ağzıyla söylenmiş uzun türküleri derleyen bir anlatım'], 'Özdemir Asaf, kısa dizelerde anlamı ters yüz eden söz oyunları ve aforizmalarla düşündürmeyi amaçlar.'),
  ('Sabahattin Ali\'nin şiirlerinde ölçü ve söyleyiş bakımından hangi özellik görülür?', 'Hece ölçüsüyle, halk türküsü havasında sade bir söyleyiş', ['Aruzla, divan şiirinin kaside biçiminde ağır bir söyleyiş', 'Ölçüsüz, anlamı kapalı ve imge yoğun bir söyleyiş', 'Fransızca dizelerle karışık, deneysel bir söyleyiş'], 'Sabahattin Ali\'nin şiirleri heceyle yazılmış, türkü gibi akıcı ve hüzünlüdür; bu yüzden pek çoğu bestelenmiştir.'),
  ('\'Sarı saçlarına deli gönlümü / Bağlamışlar çözülmüyor Mihriban\' dizelerinin şairi kimdir?', 'Abdurrahim Karakoç', ['Ömer Bedrettin Uşaklı', 'Ahmet Kutsi Tecer', 'Cahit Külebi'], 'Mihriban şiiri Abdurrahim Karakoç\'a aittir; Musa Eroğlu\'nun bestesiyle çok tanınmıştır.'),
  ('Abdurrahim Karakoç\'un şiiri için en doğru tanım hangisidir?', 'Hece ölçüsü ve halk şiiri biçimleriyle toplumsal ve lirik konuları işleyen modern bir şiir', ['Ölçüsüz ve anlamı kapalı imgelerle yazılmış soyut bir şiir', 'Aruzla yazılmış, divan geleneğini kaside ve gazel biçimleriyle sürdüren bir saray şiiri', 'Yalnızca Fransız sembolistlerini taklit eden bir salon şiiri'], 'Abdurrahim Karakoç koşma, semai gibi halk biçimlerini ve heceyi kullanarak hem aşkı hem toplumsal eleştiriyi dile getirmiştir.'),
  ('Hisarcıların hem Garip\'e hem de toplumcu şiire karşı çıkarken savundukları şiir anlayışı hangisidir?', 'Millî ve manevi değerlere bağlı, gelenekten kopmayan ölçülü bir şiir', ['Sınıf mücadelesini öne çıkaran, işçiyi eyleme çağıran militan bir şiir', 'Anlamı tamamen dağıtan, absürde dayanan bir şiir', 'Yalnız yabancı dilde yazılan kozmopolit bir şiir'], 'Hisar çevresi şiirin ne bir ideolojinin aracı ne de basit bir şaka olmasını istemiş; gelenekle bağı ve millî duyarlılığı korumayı savunmuştur.'),
  ('Mavi hareketinin kuramcısı sayılan Attila İlhan\'ın bu dergide savunduğu temel görüş hangisidir?', 'Toplumcu gerçekçi içeriği modern ve imgeli bir şiir diliyle buluşturmak', ['Şiiri tamamen siyasetten arındırıp yalnızca anlamsız ses oyunlarına dönüştürmek', 'Divan şiirine tümüyle geri dönüp aruzu yeniden egemen kılmak', 'Garip\'in yalın espri anlayışını değiştirmeden sürdürmek'], 'Attila İlhan, \'sosyal realizm\' kavramı etrafında toplumcu bir bakışı Batılı modern şiirin teknikleriyle birleştirmeyi savunmuştur.'),
  ('\'Hangi Sol\' ve \'Hangi Batı\' gibi düşünce kitaplarıyla da tanınan şair kimdir?', 'Attila İlhan', ['Can Yücel', 'Hilmi Yavuz', 'Melih Cevdet Anday'], 'Attila İlhan \'Hangi\' dizisindeki deneme kitaplarında Türk solunu ve Batılılaşmayı eleştirel bir gözle ele almıştır.'),
  ('Aşağıdaki şairlerden hangisi İkinci Yeni şairleri arasında sayılmaz?', 'Attila İlhan', ['Ülkü Tamer', 'Ercüment Uçarı', 'İlhan Berk'], 'Attila İlhan Mavi hareketinin kuramcısıdır ve İkinci Yeni\'yi eleştirmiştir. Ülkü Tamer, Turgut Uyar ve İlhan Berk İkinci Yeni şairleridir.'),
  ('İkinci Yeni şairlerinin dil kullanımındaki tutumu en iyi hangi seçenekte anlatılır?', 'Sözcükleri alışılmış anlam ve dizilişlerinden saptırarak yeni çağrışımlar üretmek', ['Konuşma dilini olduğu gibi aktarıp her sözcüğü gerçek anlamında kullanmak', 'Arapça ve Farsça tamlamalarla divan şiiri söyleyişini canlandırmak', 'Halk türkülerindeki kalıp söyleyişleri değiştirmeden aktarmak'], 'İkinci Yeni\'de dil bir araç değil, yeni anlamlar kurulan bir malzemedir; sözdizimi bozulur, beklenmedik sözcük birleşimleri yapılır.'),
  ('İkinci Yeni şairlerinin şiirde hikâye anlatmaya ve düz anlatıma karşı çıkmalarının gerekçesi hangisidir?', 'Şiirin anlatımla değil imgeyle ve çağrışımla var olacağına inanmaları', ['Şiirin uzun destanlarla halkı eğitmesi gerektiğine inanmaları', 'Şiirde yalnızca olay örgüsünün önemli olduğunu düşünmeleri', 'Şiiri yalnızca bestelenecek şarkı sözü olarak görmeleri'], 'Garip\'in anlatıya yaslanan şiirine karşı İkinci Yeni, şiirin özünü imgenin yoğunluğunda aramıştır.'),
  ('Bir şiirde \'gökyüzü bir kuyu gibi ağzını açtı tenhada / sözcüklerin kırık bilekleri ıslandı\' gibi dizeler bulunuyor; anlam doğrudan verilmiyor, beklenmedik imgeler yan yana diziliyor. Bu şiir en çok hangi anlayışa yakındır?', 'İkinci Yeni', ['Beş Hececiler', 'Garip', 'Hisar'], 'Alışılmadık imge birleşimleri, kapalı anlatım ve dilin saptırılması İkinci Yeni\'nin belirgin özellikleridir.'),
  ('İkinci Yeni şairlerinin pek çoğu 1960\'lardan sonra şiirlerinde nasıl bir değişim göstermiştir?', 'Toplumsal konulara daha açık bir şiire yönelmişlerdir.', ['Bu şairlerin şiiri bırakıp yalnız roman yazmaya geçmesi', 'Aruza dönerek gazel yazmaya başlamışlardır.', 'Garip\'in ilk dönem esprili şiirine geri dönmüşlerdir.'], '1960 sonrasının daha özgür ortamında Cemal Süreya, Turgut Uyar ve Edip Cansever gibi şairlerin şiirlerinde toplumsal duyarlılık artmıştır.'),
  ('\'Sizin hiç babanız öldü mü / Benim bir kere öldü kör oldum\' dizeleri hangi şaire aittir?', 'Cemal Süreya', ['Can Yücel', 'Edip Cansever', 'Ahmed Arif'], 'Bu dizeler Cemal Süreya\'nın babasının ölümünü yalın ama sarsıcı bir dille anlattığı şiirdendir.'),
  ('\'Hayat kısa, / Kuşlar uçuyor\' dizeleriyle hayatın geçiciliğini iki kısa sözle anlatan şair kimdir?', 'Cemal Süreya', ['Özdemir Asaf', 'Orhan Veli', 'Turgut Uyar'], 'Bu ünlü dizeler Cemal Süreya\'nındır; kısa ve yoğun söyleyişin İkinci Yeni\'deki güçlü örneklerinden sayılır.'),
  ('Cemal Süreya\'nın şiirinde en belirgin temalar hangi seçenekte doğru verilmiştir?', 'Aşk, kadın ve beden ile toplumsal duyarlılık', ['Tasavvuf, tarikat ve tevhit', 'Kahramanlık, akın ve fetih', 'Köy hayatı, hasat sevinci ve yaylaya göç'], 'Cemal Süreya aşkı ve teni cesur bir dille işleyen, aynı zamanda toplumsal duyarlılığı olan bir şairdir.'),
  ('\'Adam yaşama sevinci içinde / Anahtarını koydu masaya\' dizeleriyle başlayan ve nesneler üzerinden insanın iç dünyasını sezdiren Edip Cansever şiiri hangisidir?', 'Masa da Masaymış Ha', ['Mendilimde Kan Sesleri', 'Geyikli Gece', 'Otel Odaları'], 'Bu şiirde adam masaya anahtarını, ekmeğini, ağaçlarını, yıldızlarını koyar; masa bütün bunları taşır. Geyikli Gece Turgut Uyar\'ın, Otel Odaları Necip Fazıl\'ın şiiridir.'),
  ('\'Ahmet abi güzel şey mi yaşamak\' diye başlayan bir konuşmayla bilinen \'Mendilimde Kan Sesleri\' şiirinin şairi kimdir?', 'Edip Cansever', ['Turgut Uyar', 'Cemal Süreya', 'Ahmed Arif'], 'Mendilimde Kan Sesleri, Edip Cansever\'in en sevilen şiirlerindendir; yalnızlık ve yaşama sevinci arasında gidip gelen bir sesi taşır.'),
  ('Edip Cansever\'in şiirinde ağır basan düşünce dünyası hangi kavramlarla en iyi açıklanır?', 'Varoluşçu bunalım, yalnızlık ve insanın kendine yabancılaşması', ['Tasavvufi vahdet, zikir ve sema', 'Kahramanlık, fetih ve akıncı ruhu', 'Köy hayatının neşesi, hasat sevinci ve yayla şenlikleri'], 'Cansever\'in kişileri modern hayatın içinde yalnız, umutsuz ve kendi varlığını sorgulayan insanlardır.'),
  ('Ece Ayhan\'ın şiirlerinde sıkça yer verdiği insanlar hangi seçenekte doğru nitelenmiştir?', 'Toplumun kıyısında kalmış, resmî tarihin görmezden geldiği kimsesizler', ['Saray çevresinin ileri gelen paşaları ve vezirleri', 'Köy enstitüsü öğretmenleri ve idealist memurlar', 'Kurtuluş Savaşı\'nın ünlü komutanları ve cephedeki subaylar'], 'Ece Ayhan çırak çocukları, hamalları, azınlıkları ve kenar mahalle insanlarını şiire taşıyarak resmî tarihin dışında kalanlara ses vermiştir.'),
  ('İlhan Berk\'in şiir anlayışının sonraki dönemindeki temel özelliği hangisidir?', 'Nesnelere, sözcüklere ve imgeye odaklanıp anlamı ikinci plana iten bir şiir', ['Halkı eyleme çağıran açık, sloganlı ve kitlelere seslenen siyasal bir şiir', 'Aruzla yazılmış, tasavvufi kavramlara dayanan bir şiir', 'Hece ölçüsüyle yazılmış, memleket manzaralarını öven bir şiir'], 'Berk, şiirin anlamdan çok sözcüklerin ve imgelerin kendisiyle var olduğunu savunmuş; nesneleri ve sözcükleri şiirin merkezine almıştır.'),
  ('Sezai Karakoç\'un 1960\'tan itibaren aralıklarla yayımladığı ve kendi düşünce sistemine de ad olan dergi hangisidir?', 'Diriliş', ['Büyük Doğu', 'Mavera', 'Edebiyat'], 'Diriliş dergisi Sezai Karakoç\'un çıkardığı ve \'diriliş\' düşüncesini yaydığı yayındır. Büyük Doğu Necip Fazıl\'ın, Mavera ve Edebiyat başka İslamcı yazar çevrelerinin dergileridir.'),
  ('Sezai Karakoç\'un \'diriliş\' kavramıyla anlattığı temel düşünce hangisidir?', 'İslam medeniyetinin kendi kaynaklarına dönerek yeniden canlanması', ['Batı medeniyetini olduğu gibi benimseyip geleneksel değerleri tümüyle bırakmak', 'Şiirde ölçüyü ve kafiyeyi yeniden zorunlu kılmak', 'Halk şiirini derleyip arşivlemek'], 'Karakoç\'a göre çözülen İslam toplumu, kendi inanç ve medeniyet köklerinden yeniden doğmalıdır; dergisi ve şiirleri bu düşünceyi işler.'),
  ('Sezai Karakoç\'un şiir dışındaki eserleri için hangisi doğrudur?', 'Yunus Emre, Mehmet Akif ve İslam düşüncesi üzerine çok sayıda deneme ve inceleme yazmıştır.', ['Yalnızca çocuklar için masal kitapları yazmıştır.', 'Çok sayıda polisiye roman yayımlamıştır.', 'Şiirden başka eser vermemiş, yazı yazmamıştır.'], 'Karakoç\'un düzyazı eserleri arasında Yunus Emre, Mehmet Akif incelemeleri ve İslam\'ın Dirilişi gibi düşünce kitapları bulunur.'),
  ('\'Yaşadıklarımdan öğrendiğim bir şey var\' dizesiyle başlayan ve sevmenin bütün varlıkla sevmek olduğunu anlatan şiirin şairi kimdir?', 'Ataol Behramoğlu', ['İsmet Özel', 'Hasan Hüseyin Korkmazgil', 'Refik Durbaş'], 'Bu dize Ataol Behramoğlu\'nun aynı adlı şiirinin başlangıcıdır; şiir \'Sevdin mi, bütün benliğinle seveceksin\' gibi öğütlerle sürer.'),
  ('İsmet Özel\'in şiir ve düşünce serüveninde 1970\'lerin ortasında gerçekleşen köklü değişim hangisidir?', 'Marksist toplumcu çizgiden İslami bir dünya görüşüne yönelmesi', ['Serbest şiirden hece ölçüsüne dönüp memleket şiiri yazması', 'Şiiri tamamen bırakıp yalnız tiyatroya yönelmesi', 'Türkçe yerine Fransızca yazmaya başlaması'], '1960\'ların devrimci toplumcu şairi İsmet Özel, 1974 civarında İslam\'a yönelerek düşünce ve şiirinde yeni bir dönem başlatmıştır.'),
  ('\'Ah kimselerin vakti yok / Durup ince şeyleri anlamaya\' dizelerinin şairi kimdir?', 'Gülten Akın', ['Didem Madak', 'Nilgün Marmara', 'Lale Müldür'], 'Bu dizeler Gülten Akın\'ın \'Ah Kimselerin Vakti Yok\' şiirindendir; hızlı hayatın içinde inceliklerin kaybolmasına duyulan hüznü dile getirir.'),
  ('\'Hayatta ben en çok babamı sevdim\' dizesiyle başlayan şiirin şairi aynı zamanda bir Millî Eğitim bakanının oğludur. Bu şair kimdir?', 'Can Yücel', ['Cemal Süreya', 'Ahmed Arif', 'Attila İlhan'], 'Can Yücel, Millî Eğitim Bakanı Hasan Âli Yücel\'in oğludur; bu şiir babasına duyduğu sevgiyi anlatır.'),
  ('Can Yücel\'in çevirileri için en uygun nitelendirme hangisidir?', 'Özellikle Shakespeare çevirilerinde metni Türkçenin canlı söyleyişine uyarlayan özgür bir çeviri anlayışı', ['Kelimesi kelimesine, sözlük anlamına bağlı akademik bir çeviri anlayışı', 'Yalnız Arapçadan dinî metinlere yönelen bir çeviri anlayışı', 'Hiç şiir çevirmeyip yalnız teknik kitap çeviren bir anlayış'], 'Can Yücel, Hamlet ve Shakespeare soneleri gibi çevirilerinde metni Türkçede yeniden yazarcasına özgün bir dille aktarmıştır.'),
  ('Can Yücel\'in şiir dilinin ayırıcı özelliği hangisidir?', 'Argo, mizah ve gündelik konuşmayı lirizmle kaynaştıran canlı bir söyleyiş', ['Ağır Osmanlıca tamlamalarla örülmüş resmî bir söyleyiş', 'Yalnız aruz kalıplarına dayanan klasik bir söyleyiş', 'Anlamı tamamen dışlayan, ses oyunlarından ibaret bir söyleyiş'], 'Can Yücel sokağın dilini, şakayı ve argoyu şiire sokarak toplumsal eleştiriyi ve sevgiyi samimi bir sesle dile getirmiştir.'),
  ('Hilmi Yavuz\'un şiiri hangi özelliğiyle tanınır?', 'Divan şiiri ve tasavvuf birikimini modern şiir diliyle buluşturmasıyla', ['Hece ölçüsüyle köy manzaraları anlatmasıyla', 'Garip\'in espriye dayalı söyleyişini sürdürmesiyle', 'Toplumcu sloganlarla işçi eylemlerini anlatmasıyla'], 'Hilmi Yavuz, gelenekten beslenen bir modernizmi savunmuş; Doğu Şiirleri gibi kitaplarında divan ve tasavvuf imgelerini çağdaş bir duyarlılıkla işlemiştir.'),
  ('Didem Madak\'ın şiirini en iyi tanımlayan özellik hangisidir?', 'Kadın deneyimini gündelik nesneler, ev içi ayrıntılar ve ironik bir içtenlikle anlatması', ['Divan şiirinin kaside biçimini aruzla sürdürmesi', 'Kahramanlık destanlarını hece ölçüsüyle anlatması', 'Siyasi sloganları kısa dizelerle tekrarlaması'], 'Didem Madak, kadınların iç dünyasını, mahalle hayatını ve küçük nesneleri samimi ve hüzünlü bir ironiyle şiirleştirmiştir.'),
  ('1980 sonrası şiirde sıkça görülen \'geleneğe dönüş\' eğilimi en çok hangi biçimde ortaya çıkmıştır?', 'Divan şiiri, tasavvuf ve halk şiiri birikiminden modern bir dille yararlanma', ['Aruzu yasal olarak zorunlu kılma girişimi', 'Bütün şiirlerin Osmanlı harfleriyle basılması', 'Garip önsözünün yeniden ortak bildiri olarak yayımlanması'], 'Bu dönemin pek çok şairi eski şiirin imgelerine, tasavvufa ve halk söyleyişine modern bir bakışla dönmüştür.'),
  ('Bir öğrenci \'Bu dergi 1952-1956 arasında çıktı, kuramcısı sosyal realizmi savundu, Garip\'e karşıydı.\' notunu almış. Öğrencinin söz ettiği dergi hangisidir?', 'Mavi', ['Hisar', 'Yaprak', 'Yeditepe'], 'Anlatılan özellikler Attila İlhan\'ın kuramcısı olduğu Mavi dergisine aittir. Hisar da Garip\'e karşıdır ama gelenekçidir ve sosyal realizmi savunmaz.'),
  ('Aşağıdaki kitap ve şair eşleştirmelerinden hangisi doğrudur?', 'Umutsuzlar Parkı – Edip Cansever', ['Göçebe – Turgut Uyar', 'Körfez – Cahit Zarifoğlu', 'Duvar – Melih Cevdet Anday'], 'Umutsuzlar Parkı Edip Cansever\'indir. Göçebe Cemal Süreya\'nın, Körfez Sezai Karakoç\'un, Duvar Attila İlhan\'ın kitabıdır.'),
  ('Aşağıdaki şair ve topluluk eşleştirmelerinden hangisi yanlıştır?', 'Ahmed Arif – Hisar', ['Oktay Rifat – Garip', 'Ziya Osman Saba – Yedi Meşale', 'Ece Ayhan – İkinci Yeni'], 'Ahmed Arif toplumcu gerçekçi çizgide yer alır; Hisar ise gelenekçi bir topluluktur. Diğer eşleştirmeler doğrudur.'),
  ('Aşağıdaki şairlerden hangisi herhangi bir topluluğa bağlanmadan kendi yolunu çizen \'bağımsız\' şairler arasında sayılır?', 'Fazıl Hüsnü Dağlarca', ['Orhan Veli Kanık', 'Cevdet Kudret Solok', 'Mehmet Çınarlı'], 'Dağlarca hiçbir topluluğa katılmamıştır. Orhan Veli Garip\'e, Cevdet Kudret Yedi Meşale\'ye, Mehmet Çınarlı Hisar\'a bağlıdır.'),
  ('\'Toplu şiirlerin kitap adı – şair\' eşleştirmelerinden hangisi doğrudur?', 'Büyük Saat – Turgut Uyar', ['Sevda Sözleri – Attila İlhan', 'Çile – Asaf Halet Çelebi', 'Erbain – Sezai Karakoç'], 'Büyük Saat Turgut Uyar\'ın toplu şiirleridir. Sevda Sözleri Cemal Süreya\'nın, Çile Necip Fazıl\'ın, Erbain İsmet Özel\'in toplu şiirleridir.'),
  ('Başlığında bir kadın adı bulunan şiirlerle şairlerinin eşleştirildiği aşağıdaki seçeneklerden hangisi doğrudur?', 'Mona Roza – Sezai Karakoç', ['Lavinia – Cemal Süreya', 'Fahriye Abla – Necip Fazıl', 'Olvido – Özdemir Asaf'], 'Mona Roza Sezai Karakoç\'undur. Lavinia Özdemir Asaf\'ın, Fahriye Abla ve Olvido Ahmet Muhip Dıranas\'ın şiirleridir.'),
  ('Bir öğrenci bir şair için şu notları almış: \'Mülkiye mezunu, Darphane müdürü olmuş, Papirüs\'ü çıkarmış, Üvercinka ile tanınmış.\' Bu notlara eklenebilecek doğru bilgi hangisidir?', 'Toplu şiirleri Sevda Sözleri adıyla yayımlanmıştır.', ['Garip önsözünü kaleme almıştır.', 'Diriliş Partisi\'ni kurmuştur.', 'Kapalıçarşı\'da antika dükkânı işletmiştir.'], 'Notlar Cemal Süreya\'yı tanımlar; toplu şiirleri Sevda Sözleri\'dir. Diğer bilgiler sırasıyla Orhan Veli, Sezai Karakoç ve Edip Cansever\'e aittir.'),
  ('Aşağıdaki şiir kitaplarından hangisi İkinci Yeni şairlerinden birine ait değildir?', 'Yağmur Kaçağı', ['Kınar Hanımın Denizleri', 'Galile Denizi', 'Dirlik Düzenlik'], 'Yağmur Kaçağı Attila İlhan\'ındır. Kınar Hanımın Denizleri Ece Ayhan\'ın, Galile Denizi İlhan Berk\'in, Dirlik Düzenlik Edip Cansever\'in kitabıdır.'),
  ('Cumhuriyet\'in ilk on yılında şiirde en yaygın kullanılan ölçü hangisidir ve bunun başlıca nedeni nedir?', 'Hece ölçüsü; Millî Edebiyat\'ın millî ölçü anlayışının sürmesi', ['Aruz ölçüsü; divan şiirinin yeniden okullarda zorunlu olması', 'Serbest ölçü; Garip\'in 1923\'te yayımlanmış olması', 'Aruz ölçüsü; Yedi Meşale\'nin onu tek ölçü ilan etmesi'], '1920\'lerde Beş Hececiler ve onları izleyenler sayesinde hece ölçüsü egemendi; Garip ise 1941\'de ortaya çıkmıştır.'),
  ('Cumhuriyet döneminde aruz ölçüsünü ustalıkla kullanmayı sürdüren şairlere örnek olarak hangisi verilebilir?', 'Yahya Kemal Beyatlı', ['Orhan Veli Kanık', 'Cemal Süreya', 'Ahmed Arif'], 'Yahya Kemal Cumhuriyet döneminde de aruzu kusursuz bir biçimde kullanmıştır. Diğer üç şair serbest ölçüyle yazmıştır.'),
  ('Toplumcu gerçekçi şiirle saf (öz) şiir arasındaki temel ayrım hangisidir?', 'Toplumcu şiir toplumu değiştirmeyi amaçlar; saf şiir şiirin kendi güzelliğini ve ahengini amaç sayar.', ['Toplumcu şiir yalnız aruzla, saf şiir yalnız heceyle yazılır.', 'Toplumcu şiir yalnız çocuklara, saf şiir yalnız yaşlılara seslenir.', 'İkisi arasında amaç farkı yoktur, yalnız dönemleri farklıdır.'], 'Toplumcu şiir sanatı toplumsal mücadelenin aracı sayarken saf şiir sanatın kendi değerini, musikiyi ve imgeyi esas alır.'),
  ('Bir şiirde şu özellikler var: hece ölçüsü, yayla ve köy manzaraları, Anadolu\'ya duyulan hayranlık, sade bir İstanbul Türkçesi. Bu şiir hangi anlayışa en yakındır?', 'Memleketçi hece şiiri', ['İkinci Yeni', 'Garip', 'Mavi hareketi'], 'Hece ölçüsü ve Anadolu manzaraları, Beş Hececiler\'in ve onları izleyen memleketçi şairlerin özelliğidir.'),
  ('Bir şiirde şu özellikler var: işçi ve köylünün sömürülmesi, kurtuluşa olan inanç, destansı bir anlatım, serbest ölçü. Bu şiir en çok hangi çizgiye uyar?', 'Toplumcu gerçekçi şiir', ['Saf şiir', 'Yedi Meşale', 'Hisar'], 'Emekçinin sorunlarını işleyen, umut ve mücadeleyi öne çıkaran serbest şiir toplumcu gerçekçi çizgiye aittir.'),
  ('Bir şiirde şu özellikler var: Budist ve tasavvufi kavramlar, büyülü bir ses tekrarı, eski Mısır ve Bizans\'a göndermeler. Bu şiir en çok hangi şairin şiirine benzer?', 'Asaf Halet Çelebi', ['Cahit Külebi', 'Rıfat Ilgaz', 'Oktay Rifat'], 'Doğu mistisizmi, ses büyüsü ve eski uygarlık göndermeleri Asaf Halet Çelebi\'nin şiirine özgüdür.'),
  ('Bir şiirde şu özellikler var: kişiler konuşturuluyor, bir tiyatro sahnesi gibi kurulmuş bölümler var, varoluşçu bir yalnızlık hissediliyor. Bu şiir en çok hangi şairi akla getirir?', 'Edip Cansever', ['Arif Nihat Asya', 'Faruk Nafiz Çamlıbel', 'Orhan Seyfi Orhon'], 'Şiire tiyatro tekniğini taşıyan ve varoluşçu yalnızlığı işleyen İkinci Yeni şairi Edip Cansever\'dir.'),
  ('Garip ile toplumcu gerçekçi şiirin ortak yönü aşağıdakilerden hangisidir?', 'Şiirde sıradan insana yer vermeleri ve serbest ölçüyü kullanmaları', ['İkisinin de divan şiirinin süslü dilini sürdürmesi', 'İkisinin de metafizik ve dinî temaları öne çıkarması', 'İkisinin de anlamı bilinçli olarak kapalı tutması'], 'Her iki anlayış da şiire sıradan insanı ve serbest ölçüyü taşır; ancak Garip bireysel ve ironik, toplumcu şiir ise ideolojik ve mücadeleci bir tavır taşır.'),
  ('\'Yaşamak şakaya gelmez, / büyük bir ciddiyetle yaşayacaksın / bir sincap gibi mesela\' dizeleri Nazım Hikmet\'in hangi şiirindendir?', 'Yaşamaya Dair', ['Hapiste Yatacak Olana Dair Bazı Öğütler', 'Masalların Masalı', 'Kerem Gibi'], '\'Yaşamaya Dair\', yaşamın ciddiyetle ve sevgiyle sürdürülmesi gerektiğini anlatan üç bölümlü bir şiirdir.'),
  ('Garip hareketinin bir topluluk olarak sona ermesi genellikle hangi olayla ilişkilendirilir?', 'Orhan Veli\'nin 1950\'de ölümüyle', ['Hisar\'ın 1980\'de kapanmasıyla', 'Nazım Hikmet\'in 1951\'de yurt dışına çıkmasıyla', 'Varlık\'ın 1946\'da İstanbul\'a taşınmasıyla'], 'Hareketin öncüsü ve en etkili sesi olan Orhan Veli\'nin ölümüyle Garip bir topluluk olarak sona ermiş; Oktay Rifat ve Melih Cevdet farklı yollara gitmiştir.'),
  ('\'Rakı şişesinde balık olsam\' dizesi, sıradan bir nesneyi şiire taşıyan hangi şaire aittir?', 'Orhan Veli', ['Fazıl Hüsnü Dağlarca', 'Cahit Sıtkı Tarancı', 'Ahmet Muhip Dıranas'], 'Bu dize Orhan Veli\'nindir; gündelik nesneleri şiire sokma tavrının tipik bir örneğidir.'),
  ('\'En güzel deniz: / henüz gidilmemiş olanıdır\' dizeleriyle umudu geleceğe bağlayan şair kimdir?', 'Nazım Hikmet', ['Cemal Süreya', 'Attila İlhan', 'Melih Cevdet Anday'], 'Bu dizeler Nazım Hikmet\'e aittir; en güzel günlerin, çocukların ve sözlerin henüz yaşanmamış olanlar olduğunu söyleyen umut dolu bir şiirden alınmıştır.'),
  ('\'Ben içeri düştüğümden beri / güneşin etrafında on kere döndü dünya\' dizeleriyle başlayan şiirin şairi kimdir?', 'Nazım Hikmet', ['Ahmed Arif', 'Sabahattin Ali', 'Rıfat Ilgaz'], 'Bu dizeler Nazım Hikmet\'in \'Ben İçeri Düştüğümden Beri\' şiirindendir; hapiste geçen yıllara karşın umudun sürdüğünü anlatır.'),
  ('\'Haydi Abbas, vakit tamam; / Akşam diyordun işte oldu akşam\' dizeleriyle bir arabacıya seslenen şiirin şairi kimdir?', 'Cahit Sıtkı Tarancı', ['Orhan Veli Kanık', 'Faruk Nafiz Çamlıbel', 'Necip Fazıl Kısakürek'], '\'Abbas\' şiiri Cahit Sıtkı\'nındır; ölüm duygusu, yolcu ve akşam imgeleriyle sezdirilir.'),
  ('1928\'de Latin alfabesine geçilmesinin şiir okuru açısından en önemli sonucu hangisidir?', 'Okuryazarlığın artmasıyla şiirin daha geniş bir kitleye ulaşabilmesi', ['Şiirin yalnızca saray çevresinde ve medreselerde okunur hâle gelmesi', 'Aruz ölçüsünün yasayla zorunlu kılınması', 'Bütün eski şiirlerin yasaklanıp yok edilmesi'], 'Yeni harflerle öğrenmesi kolay bir yazıya geçilmesi okuryazarlığı artırmış, dergi ve kitapların okur kitlesini genişletmiştir.'),
  ('1932\'de Türk Dil Kurumunun kurulmasıyla başlayan dilde özleştirme hareketinin Cumhuriyet şiirine yansıması nasıl değerlendirilebilir?', 'Pek çok şair Arapça-Farsça sözcükler yerine Türkçe karşılıkları kullanmaya yönelmiştir.', ['Şairler Türkçeyi bırakıp Fransızca yazmaya başlamıştır.', 'Şiirde yalnızca Arapça ve Farsça kökenli Osmanlıca tamlamalar kullanılmaya başlanmıştır.', 'Şiir yazmak bir süre için tümüyle yasaklanmıştır.'], 'Dil Devrimi\'nin etkisiyle şiir dili sadeleşmiş; Dağlarca, Necatigil ve sonraki pek çok şair öz Türkçe sözcüklere yer vermiştir.'),
  ('1932\'de kurulan Halkevlerinin edebiyat ve şiir üzerindeki etkisi en iyi hangisiyle açıklanır?', 'Dergileri ve derleme çalışmalarıyla halk kültürünü ve yerel şairleri görünür kılması', ['Yalnızca divan şiiri dersleri vererek aruzu yaygınlaştırması', 'Bütün bağımsız şiir dergilerini kapatarak yayın hayatını tek elde toplaması', 'Yalnızca Batı operası sahnelemesi'], 'Halkevleri Ülkü gibi dergiler çıkarmış, halk edebiyatı derlemeleri yapmış ve Anadolu\'daki halk şairlerinin tanınmasına katkı sağlamıştır.'),
  ('1960 askerî müdahalesinin ardından kabul edilen 1961 Anayasası\'nın getirdiği görece özgürlük ortamı şiire nasıl yansımıştır?', 'Toplumcu şiirin yeniden güç kazanmasına ve 1960 kuşağının ortaya çıkmasına zemin hazırlamıştır.', ['Şiirin tümüyle yasaklanmasına ve dergilerin kapanmasına yol açmıştır.', 'Şairlerin topluca aruza dönmesine neden olmuştur.', 'Garip\'in ortak kitabının ilk kez yayımlanmasını sağlamıştır.'], '1960\'larda Nazım\'ın kitaplarının yeniden basılması ve toplumcu dergilerin çoğalmasıyla toplumcu şiir yeniden canlanmıştır.'),
  ('1946\'da çok partili hayata geçişle aynı yıl CHP\'nin bir şiir yarışması düzenlemesi, dönemin kültür politikası hakkında ne düşündürür?', 'Devletin ve partinin edebiyatı teşvik etmeyi bir kültür politikası olarak görmesi', ['Şiirin devlet tarafından yasaklanmak istendiğini', 'Siyasi partilerin edebiyatla hiçbir biçimde ilgilenmediğini ve onu önemsemediğini', 'Yarışmaya yalnız yabancı şairlerin katılabildiğini'], 'Tek parti döneminin sonlarına doğru düzenlenen bu yarışma, Halkevleri ve Tercüme Bürosu gibi kurumlarla birlikte devletin kültür hayatını yönlendirme isteğini gösterir.'),
  ('1940\'ta kurulan Tercüme Bürosu ile Dünya Edebiyatından Tercümeler dizisinin Cumhuriyet şiirine katkısı hangisidir?', 'Batı ve klasik şiirin Türkçeye kazandırılmasıyla şairlerin ufkunu genişletmesi', ['Divan şiirini yeniden tek örnek hâline getirmesi', 'Şairlerin yalnızca halk şiiri biçimlerinde ve hece ölçüsüyle yazmasını zorunlu kılması', 'Yabancı şiirin okunmasını yasaklaması'], 'Bu dizide yapılan çeviriler, Orhan Veli gibi çevirmen-şairler eliyle Türk şiirine yeni biçim ve duyarlılıklar taşımıştır.'),
  ('12 Mart 1971 muhtırasının ardından gelen dönemde toplumcu şairlerin yaşadığı deneyim şiire en çok nasıl yansımıştır?', 'Tutuklama, cezaevi ve direniş temalarının şiirde yoğunlaşmasıyla', ['Şairlerin topluca şiiri bırakıp çocuk masalına yönelmesiyle', 'Aruzla yazılmış saray kasidelerinin çoğalmasıyla', 'İkinci Yeni\'nin ortak bildirisinin yazılmasıyla'], '1970\'lerde pek çok şair yargılanmış ya da tutuklanmış; cezaevi, direniş ve umut bu dönem toplumcu şiirinin belirgin konuları olmuştur.'),
  ('Cumhuriyet dönemi şiirinin ilk yıllarında Kurtuluş Savaşı ve Atatürk\'ün sık sık konu edilmesinin en önemli nedeni hangisidir?', 'Yeni devletin kuruluş coşkusunun ve millî kimlik bilincinin şiire yansıması', ['Şairlerin yalnızca yabancı savaşları anlatmak istemesi', 'Divan şiirinin geleneksel kurallarının bu konuları işlemeyi zorunlu kılması', 'Halkın bu konulardan hiç haberdar olmaması'], 'Yeni Cumhuriyet\'in kuruluş heyecanı, millî mücadele ve kurucu önder temaları, dönemin pek çok şairinde coşkulu bir dille işlenmiştir.'),
  ('Köy Enstitülerinden yetişen yazar ve şairlerin Cumhuriyet edebiyatına katkısı en çok hangi alanda olmuştur?', 'Köy ve köylü gerçeğini içeriden, yaşanmış bir deneyimle anlatmalarında', ['Divan şiirini yeniden canlandırmalarında', 'Yalnızca Paris\'teki salon hayatını anlatmalarında', 'Bilim kurgu ve fantastik anlatı türlerini Türk edebiyatına ilk kez getirmelerinde'], 'Köy kökenli bu yazarlar, daha önce dışarıdan anlatılan köyü kendi deneyimleriyle ve gerçekçi bir bakışla edebiyata taşımıştır.'),
  ('1923-1940 arasındaki Türk şiiri için aşağıdaki yargılardan hangisi doğrudur?', 'Hece ve aruzla yazan şairlerin yanında Nazım Hikmet\'le serbest ve toplumcu bir şiir de ortaya çıkmıştır.', ['Bu dönemde yalnızca İkinci Yeni şairleri ürün vermiştir.', 'Bu dönemde hiçbir şiir kitabı yayımlanmamıştır.', 'Bu dönemde Garip hareketi en güçlü dönemini yaşamıştır.'], 'Bu yıllarda Hececiler, Yedi Meşaleciler, Yahya Kemal gibi aruzcular ve Nazım Hikmet\'in serbest şiiri yan yana bulunur; Garip 1941\'de, İkinci Yeni 1950\'lerde ortaya çıkmıştır.'),
  ('1980 sonrasında yayın dünyasında artan dergi ve şiir kitabı sayısının şiir ortamına etkisi için hangisi söylenebilir?', 'Tek bir egemen akım yerine çok sesli ve çeşitli bir şiir ortamının oluşması', ['Bütün şairlerin tek bir topluluk altında birleşip ortak bir bildiri yayımlaması', 'Şiirin yerini tamamen aruzlu kasidelerin alması', 'Şiir dergilerinin tamamen ortadan kalkması'], '1980\'lerden sonra ortak bir hareketin egemenliğinden söz etmek güçleşmiş; birbirinden farklı eğilimler aynı anda var olmuştur.'),
  ('Nazım Hikmet\'in \'Akrep Gibisin Kardeşim\' şiirinde eleştirdiği insan tipi hangisidir?', 'Haksızlığa ses çıkarmadan korkuyla yaşayan, edilgin insan', ['Zenginliğini halkıyla paylaşan cömert insan', 'Ülkesi için savaşan cesur asker', 'Sanatı için her şeyini, ailesini ve evini bile feda eden yalnız bir şair'], 'Şiirde \'korkak bir karanlık içindesin akrep gibi\' denerek kendi durumunun farkına varmayan, sömürüye boyun eğen insan eleştirilir.'),
  ('Garip şairlerinin şiirde konuşma dilinin sözcüklerini, hatta argoyu kullanmaktan çekinmemeleri hangi görüşlerinin sonucudur?', 'Şiirin özel bir \'şiir dili\' gerektirmediği, her sözcüğün şiire girebileceği görüşünün', ['Şiirin yalnızca eğitimli seçkinlere yönelmesi gerektiği görüşünün', 'Şiirin divan geleneğine sadık kalması gerektiği görüşünün', 'Şiirin yalnız Fransızca yazılabileceği görüşünün'], 'Garip, şiirsel sayılan sözcüklerle sıradan sözcükler arasındaki ayrımı kaldırmış; gündelik dilin her öğesini şiire açmıştır.'),
  ('Aşağıdaki dizelerden hangisi Garip anlayışına en uygun olanıdır?', 'Bugün de işe geç kaldım, / Şef yine kaşlarını çattı; / Neyse, öğle yemeği güzeldi.', ['Ey gözlerinde yıldızların sırrı gizli olan nigâr, / Gönlüm senin aşkınla yanar ateş-bâr', 'Dağlar dağlar, yüce dağlar, / Yiğit ölür, ana ağlar', 'Mavi bir kuşun kırık sesinde / Ölümün akşam saatleri uzar'], 'İlk seçenekteki gündelik konu, konuşma dili, kafiyesizlik ve hafif ironi Garip\'in özellikleridir. Diğerleri sırasıyla divan, halk ve imgeci şiir havası taşır.'),
  ('Aşağıdaki dizelerden hangisi İkinci Yeni anlayışına en yakındır?', 'Bir eylül kuşu düştü aynanın içine / Saatler ıslak bir ağaçtan sarktı', ['Kalk sabah oldu, tarlaya gidelim, / Ekinler sararmış, orağı alıp biçelim, yorulalım', 'Bugün maaş günü, / Bakkala borcu ödedik', 'Ey şanlı ordu, ileri, / Vatan senindir, bayrak senin'], 'Mantık dışı imge birleşimleri ve kapalı anlatım İkinci Yeni\'ye özgüdür. Diğer seçenekler sırasıyla köy şiiri, Garip ve marş havasındadır.'),
  ('Aşağıdaki dizelerden hangisi toplumcu gerçekçi şiirin özelliklerini en açık biçimde taşır?', 'Fabrikanın düdüğü öttü sabahın beşinde, / Ekmeğimiz terimizde, kavgamız ellerimizde', ['Gül dalında bir bülbül öter / Sevdiğim gelmez, gece geçer', 'Saksıda bir çiçek, masada bir bardak, / Pazar sabahı, uyku', 'Ruhumun derinliğinde bir ses yankılanır: / Nereden geldim, nereye giderim ben'], 'Emekçi, fabrika ve mücadele vurgusu toplumcu gerçekçi şiirin tipik öğeleridir.'),
  ('Aşağıdaki dizelerden hangisi Necip Fazıl\'ın ilk dönem şiirinin havasını en iyi yansıtır?', 'Gece, bir sokak lambası ve ben, / Ürperiyor içim, adımlarım titrek', ['Hey koca dağlar, Anadolu\'nun yiğit oğulları, / Atlar kişner, kılıçlar parlar', 'Pazar günü vapura bindik, / Simit attık martılara', 'Fabrikada vardiya bitti, / Grev çadırı kuruldu'], 'Gece, sokak, yalnızlık ve iç ürperti Necip Fazıl\'ın Kaldırımlar dönemi şiirinin temel öğeleridir.'),
  ('Aşağıdaki dizelerden hangisi Hececilerin memleketçi şiir anlayışına en uygundur?', 'Yayla yolunda bir çoban kaval çalar, / Kuzular otlar, yeşil yamaçta güneş', ['Kahvede bir dergi okudum, sıkıldım, / Sigaramı yakıp çıktım', 'Taşın yüzünde bir göz açıldı karanlığa / Ve kuşlar unuttu dillerini, saatler kırıldı', 'Ekmek için dövüşen ellerimiz, / Yarın bizimdir, kardeşim'], 'Anadolu manzarası, çoban ve kaval imgeleri, sade dil ve ahenkli söyleyiş memleketçi hece şiirinin özellikleridir.'),
  ('Aşağıdaki dizelerden hangisi saf (öz) şiir anlayışına en yakındır?', 'Akşam, sularda eriyen bir musiki, / Uzak bir rüyada yanan altın ışık', ['Vergi dairesinde sıra bekledim, / Memur gülümsemedi', 'Kalkın ey işçiler, zincirler kırılsın artık, / Yarın bizimdir, fabrikalar bizimdir', 'Haydi çocuklar, okula koşalım, / Bayrağı selamlayalım'], 'Musiki, rüya, akşam ve ışık imgeleriyle anlamdan çok duyguyu ve ahengi öne çıkaran dizeler saf şiir anlayışına uygundur.'),
  ('Ece Ayhan\'ın şiirinin okur için en zorlu yanı hangisidir?', 'Kırık sözdizimi ve çözülmesi güç tarihsel göndermelerle örülmüş yoğun kapalılığı', ['Uzun ve ayrıntılı olay örgüleriyle roman gibi olması', 'Yalnızca hece ölçüsünün kalıplarına bağlı kalması', 'Her dizesinin bir atasözü gibi açık bir öğüt vermesi'], 'Ece Ayhan\'ın şiirinde noktalama, sözdizimi ve göndermeler bilinçli olarak yoğunlaştırılır; okurdan dikkatli bir çözümleme ister.'),
  ('İkinci Yeni şairlerinin şiirinde noktalama işaretlerini ve dilbilgisi kurallarını zaman zaman bilerek bozmalarının amacı nedir?', 'Alışkanlıkla okunan dili kırarak okuru yeni anlamlar üretmeye zorlamak', ['Matbaa hatalarını gizlemek', 'Şiiri daha kolay ezberlenir kılmak', 'Divan şiirinin eski imla kurallarına ve Arap harfli yazımın düzenine geri dönmek'], 'Dilbilgisinden sapma, İkinci Yeni\'de sıradan algıyı bozarak şiire yeni çağrışım alanları açmanın bir yoludur.'),
  ('Behçet Necatigil\'e \'evler şairi\' denmesinin nedeni hangisidir?', 'Şiirlerinde ev, aile ve orta sınıf insanının gündelik hayatını sürekli işlemesi', ['Mimar olarak pek çok ev tasarlaması', 'Şiirlerini yalnızca evde okunmak üzere plağa okuyup kayda alması', 'Ev eşyası satan bir dükkân işletmesi'], 'Necatigil\'in şiiri kira, geçim, aile içi ilişkiler ve ev gibi küçük insanın dünyasına odaklanır.'),
  ('Orhan Veli\'nin \'İstanbul\'u Dinliyorum\' şiirinde şehir ağırlıklı olarak hangi duyu yoluyla okura aktarılır?', 'İşitme', ['Tatma', 'Koklama', 'Dokunma'], 'Şair gözleri kapalı İstanbul\'u dinler; kuş sesleri, satıcıların bağırışları, su sesleri gibi işitsel imgelerle şehri canlandırır.'),
  ('Orhan Veli\'nin sıradan bir memurun nasırından yakınmasını anlatan şiirine Osmanlıca ve ağırbaşlı \'Kitabe-i Seng-i Mezar\' başlığını koyması nasıl bir etki yaratır?', 'Görkemli başlık ile sıradan içerik arasındaki karşıtlıktan doğan bir ironi', ['Şiire dinî bir ciddiyet ve bir cami vaazının ağırbaşlı havasını kazandırma', 'Şiiri bir tarih kitabının bölümü gibi gösterme', 'Okura divan şiirinin kurallarını öğretme'], 'Mezar taşı kitabeleri genellikle büyük kişiler için yazılır; Orhan Veli bu kalıbı sıradan bir adam için kullanarak ironik bir etki yaratır.'),
  ('Nazım Hikmet\'in \'Dörtnala gelip Uzak Asya\'dan Akdeniz\'e bir kısrak başı gibi uzanan bu memleket\' ifadesinde memleket neye benzetilir ve bu benzetme neye dayanır?', 'Kısrak başına; ülkenin haritadaki biçimine ve Asya\'dan gelen göçe', ['Bir gemiye; ülkenin denizcilik tarihine', 'Bir kartala; ülkenin bayrağında ve armasında yer alan simgeye', 'Bir ağaca; ülkenin ormanlarının çokluğuna'], 'Anadolu\'nun haritadaki görünümü uzanan bir at başına benzetilir; \'dörtnala gelmek\' ise Türklerin Orta Asya\'dan gelişini çağrıştırır.'),
  ('Necip Fazıl\'ın \'Kaldırımlar, çilekeş yalnızlığımın annesi\' dizesinde kaldırımlar nasıl bir varlık olarak görülür?', 'Yalnız adamın sığındığı, onu anlayan bir yoldaş ve koruyucu', ['Şairin nefret ettiği, her gece kaçıp kurtulmak istediği bir düşman', 'Yalnızca trafik düzenini sağlayan bir yapı', 'Şairin satın almak istediği bir mülk'], 'Şair kaldırımları kişileştirerek onları yalnızlığının annesi, gece yürüyüşlerinin tek yoldaşı olarak görür.'),
  ('Ahmed Arif\'in \'Anadolu\' şiirinde \'Beşikler vermişim Nuh\'a\' demesi Anadolu\'nun hangi özelliğini öne çıkarır?', 'Çok eski çağlardan beri insanlığa yurt olmuş kadim bir toprak olmasını', ['Yalnızca son yüzyılda kurulmuş, geçmişi olmayan yeni bir yerleşim olmasını', 'Ormanlarından beşik yapılıp yurt dışına satılmasını', 'Denizlerle çevrili bir ada olmasını'], 'Nuh tufanına kadar uzanan bu gönderme, Anadolu\'nun insanlık tarihinin en eski yurtlarından biri olduğunu vurgular.'),
  ('Ataol Behramoğlu\'nun \'Yaşadıklarımdan Öğrendiğim Bir Şey Var\' şiirinin ana düşüncesi hangisidir?', 'Sevmenin, yaşamanın ve inanmanın yarım değil, bütün benlikle yapılması gerektiği', ['İnsanın hiçbir şeye bağlanmadan yaşaması gerektiği', 'Geçmişi unutup yalnız para kazanmaya bakmak gerektiği', 'Şiirin yalnızca kurallara uyularak yazılabileceği'], 'Şiirde \'Sevdin mi, bütün benliğinle seveceksin\' gibi öğütlerle tam ve içten bir yaşam savunulur.'),
  ('Özdemir Asaf\'ın \'Yalnızlık paylaşılmaz, / Paylaşılsa yalnızlık olmaz\' dizelerinde dikkat çeken düşünce yapısı hangisidir?', 'Bir kavramın kendi tanımı gereği paylaşılamayacağını gösteren çelişkili gibi görünen bir mantık', ['Yalnızlığın kolayca paylaşılıp çoğalabileceğini savunan bir öğüt', 'Yalnızlığın yalnız köylerde yaşandığını anlatan bir betimleme', 'Yalnızlığın bir hastalık olduğunu açıklayan tıbbi bir bilgi'], 'Şair, yalnızlığın paylaşıldığı anda yalnızlık olmaktan çıkacağını kısa ve keskin bir mantık oyunuyla anlatır.'),
  ('Cemal Süreya\'nın \'Hayat kısa, / Kuşlar uçuyor\' dizelerinde iki kısa yargının yan yana konmasıyla ne sezdirilir?', 'Ömrün geçiciliği karşısında anı yaşamanın ve özgürlüğün önemi', ['Kuşların göç yollarına dair bilimsel bir gözlem', 'Hayatın çok uzun olduğu ve hiçbir şey için acele etmemek gerektiği', 'Avcılığın yasaklanması gerektiğine dair bir çağrı'], 'Aralarında açık bir bağlaç olmayan iki yargı, ömrün kısalığı ile uçup giden kuşlar arasında okurun kuracağı bir anlam boşluğu bırakır.'),
  ('Cahit Sıtkı\'nın \'Memleket İsterim\' şiirinde düşlenen ülkenin en belirgin özelliği hangisidir?', 'Herkesin huzur ve eşitlik içinde, kardeşçe yaşadığı sade bir dünya', ['Büyük orduları, görkemli sarayları ve geniş toprakları olan güçlü bir imparatorluk', 'Yalnızca zenginlerin yaşadığı lüks bir şehir', 'Fabrikaların her yeri kapladığı sanayi bölgesi'], 'Şiirde gökyüzünün mavi, dalın yeşil olduğu, insanların birbirini sevdiği huzurlu bir yurt özlemi dile getirilir.'),
  ('Özdemir Asaf\'ın \'Lavinia\' şiirinde sevgiliye \'gitme\' denmeyip ceket uzatılması nasıl bir sevgi anlayışını yansıtır?', 'Sevdiğini zorla tutmayan, onun özgürlüğüne saygı gösteren ama şefkatini esirgemeyen bir sevgi', ['Sevgiliyi kıskançlıkla eve kapatan, her adımını denetleyen baskıcı ve bencil bir sevgi', 'Sevgiliye karşı tamamen ilgisiz ve soğuk bir tutum', 'Sevgiliden yalnızca maddi çıkar bekleyen bir ilişki'], 'Şair sevgilisini gitmekte özgür bırakır, yine de üşümesin diye ceketini verir; sevgi burada saygı ve özenle birleşir.'),
  ('Attila İlhan\'ın \'Ben sana mecburum bilemezsin / Adını mıh gibi aklımda tutuyorum\' dizelerinde dile getirilen duygu hangisidir?', 'Kurtulunamayan, tutkulu ve kaçınılmaz bir bağlılık', ['Sevgiliyi tamamen unutmuş olmanın rahatlığı', 'Sevgiliye duyulan öfke ve intikam isteği', 'Sevgiliyle yapılan bir iş anlaşmasının resmî ve soğuk dilini taklit eden bir alay'], '\'Mecburum\' ve \'mıh gibi\' ifadeleri, şairin sevgiliye irade dışı, sökülüp atılamayan bir tutkuyla bağlı olduğunu gösterir.'),
  ('Ahmed Arif\'in \'Terketmedi sevdan beni / Aç kaldım, susuz kaldım\' dizelerinde sevda nasıl bir işlev görür?', 'Yokluk ve baskı karşısında şairi ayakta tutan bir direnç kaynağı', ['Şairi zayıf düşürüp teslim olmaya ve davasından vazgeçmeye zorlayan ağır bir yük', 'Şairin kurtulmak istediği geçici bir heves', 'Şairin yalnızca yazın hissettiği mevsimlik bir duygu'], 'Açlık, susuzluk ve hapis gibi koşullara karşın sevdanın şairi terk etmemesi, onu güçlü tutan bir dayanak olduğunu gösterir.'),
  ('Sabahattin Ali\'nin \'Aldırma gönül aldırma\' nakaratı, cezaevi koşullarında yazılan şiirde hangi tutumu dile getirir?', 'Acılara boyun eğmeden kendini teselli edip direnme', ['Kendini bütünüyle kaderine bırakıp hiçbir şey yapmadan ölümü sessizce beklemek', 'Gardiyanlara yalvarıp af dilemek', 'Dışarıdaki dostlarına öfke duyup onları suçlamak'], 'Nakarat, gönle \'aldırma\' diyerek zor koşullar karşısında dik durmayı, umudu korumayı öğütler.'),
  ('Faruk Nafiz\'in \'Han Duvarları\' şiirinde anlatıcının duvarlarda okuduğu yazıların şiire kattığı duygu hangisidir?', 'Gurbete düşmüş yolcuların hasretini ve yalnızlığını paylaşma', ['Hanın sahibine duyulan öfke ve şikâyet', 'Ticarette kazanılan büyük kârların ve kervanların zenginliğinin coşkulu sevinci', 'Bir mimarın hanın yapısını övmesi'], 'Duvarlara yazılmış dizeler, daha önce oradan geçmiş yolcuların hasret ve acılarını anlatıcıya, dolayısıyla okura aktarır.'),
  ('Orhan Veli\'nin şiirlerinde \'ben\' diye konuşan sesin çoğu zaman sıradan bir şehirli gibi konuşması, okurla nasıl bir ilişki kurar?', 'Okurla eşit düzeyde, samimi ve yakın bir konuşma havası', ['Okuru küçümseyen, yukarıdan bakan bir hitap', 'Okuru korkutup uzaklaştıran ürkütücü bir ses', 'Okura yalnızca emir veren, onu bir memur gibi gören resmî ve buyurgan bir tavır'], 'Orhan Veli\'nin şiirindeki ses, kahramanlık ya da kehanet iddiası taşımayan, okurun yanında duran sıradan bir insanın sesidir.'),
  ('Behçet Necatigil\'in şiirlerinde kira, borç ve geçim gibi konuların sıkça yer alması hangi sınıfın yaşamını yansıtır?', 'Şehirli dar gelirli orta sınıfın', ['Büyük toprak sahibi ağaların ve köylerdeki eşrafın', 'Saray çevresindeki paşaların', 'Göçebe yaşayan çobanların'], 'Necatigil\'in şiiri, apartman dairelerinde yaşayan memur ve öğretmen gibi dar gelirli şehirlilerin sıkıntılarını anlatır.'),
  ('Aşağıdaki şairlerden hangisi saf (öz) şiir çizgisinde değerlendirilmez?', 'Rıfat Ilgaz', ['Ahmet Muhip Dıranas', 'Ziya Osman Saba', 'Cahit Sıtkı Tarancı'], 'Rıfat Ilgaz toplumcu gerçekçi bir şairdir; diğerleri bireysel duyarlılığı ve ahengi öne çıkaran saf şiir çizgisindedir.'),
  ('Aşağıdaki şairlerden hangisi İslami duyarlılığı şiirinin merkezine alanlar arasında sayılmaz?', 'Orhan Veli Kanık', ['Cahit Zarifoğlu', 'Erdem Bayazıt', 'Sezai Karakoç'], 'Orhan Veli Garip\'in kurucusudur ve dinî temalara yönelmemiştir; diğer üç şair İslami duyarlılıklı şiirin önde gelenleridir.'),
  ('Aşağıdaki şair gruplarından hangisinin üyeleri aynı şiir hareketine mensuptur?', 'Ülkü Tamer, Ece Ayhan, Edip Cansever', ['Orhan Veli, Ahmed Arif, Sezai Karakoç', 'Faruk Nafiz, Cemal Süreya, Rıfat Ilgaz', 'Yaşar Nabi, Attila İlhan, Turgut Uyar'], 'Ülkü Tamer, Ece Ayhan ve Edip Cansever İkinci Yeni şairleridir. Diğer gruplarda farklı hareketlerden şairler karışık verilmiştir.'),
  ('Aşağıdaki şairlerden hangisi hem şiir yazıp hem de bir şiir hareketinin kuramını oluşturan yazılarıyla öne çıkmıştır?', 'Attila İlhan', ['Ziya Osman Saba', 'Ahmet Muhip Dıranas', 'Cahit Külebi'], 'Attila İlhan Mavi hareketinin kuramcısıdır. Diğer şairler kuramsal yazılarından çok şiirleriyle tanınır.'),
  ('Aşağıdaki şairlerden hangisi tek bir şiir kitabıyla geniş bir okur kitlesine ulaşmasıyla tanınır?', 'Ahmed Arif', ['Fazıl Hüsnü Dağlarca', 'İlhan Berk', 'Behçet Necatigil'], 'Ahmed Arif\'in yayımlanmış tek şiir kitabı Hasretinden Prangalar Eskittim\'dir. Diğer üç şair çok sayıda kitap yayımlamıştır.'),
  ('Aşağıdaki şair çiftlerinden hangisi aynı edebiyat dergisinin kurucuları arasında yer alır?', 'Ataol Behramoğlu ve İsmet Özel', ['Orhan Veli ve Sezai Karakoç', 'Necip Fazıl Kısakürek ve Cemal Süreya', 'Faruk Nafiz ve Ece Ayhan'], 'Ataol Behramoğlu ile İsmet Özel 1970\'te Halkın Dostları dergisini birlikte çıkarmıştır.'),
  ('Aşağıdakilerden hangisi şiirlerinde halk şiiri ve türkü söyleyişinden belirgin biçimde yararlanan şairleri bir arada verir?', 'Cahit Külebi, Enver Gökçe, Ahmet Kutsi Tecer', ['Ece Ayhan, İlhan Berk, Asaf Halet Çelebi', 'Ahmet Hamdi Tanpınar, Yahya Kemal, Ahmet Muhip Dıranas', 'Cemal Süreya, Edip Cansever, Turgut Uyar'], 'Külebi, Gökçe ve Tecer türkü ve halk şiiri söyleyişini şiirlerinde kullanmıştır. Diğer gruplar imgeci, klasik ya da saf şiir çizgisindedir.'),
  ('Aşağıdaki şairlerden hangisi şiirle birlikte resim sanatında da önemli eserler vermiştir?', 'Bedri Rahmi Eyüboğlu', ['Ömer Bedrettin Uşaklı', 'Rıfat Ilgaz', 'Ahmet Kutsi Tecer'], 'Bedri Rahmi Eyüboğlu, Türk resminin önemli ressamlarındandır ve şiirleriyle de tanınır.'),
  ('Aşağıdaki şairlerden hangisi yaşamının bir döneminde ülkesinden uzakta yaşamak zorunda kalmış ve yurt dışında ölmüştür?', 'Nazım Hikmet', ['Orhan Veli Kanık', 'Behçet Necatigil', 'Ahmet Muhip Dıranas'], 'Nazım Hikmet 1951\'de Türkiye\'den ayrılmış ve 1963\'te Moskova\'da ölmüştür. Diğer şairler Türkiye\'de ölmüştür.'),
  ('Aşağıdaki şairlerden hangisi aynı zamanda önemli bir çevirmen olarak Batı edebiyatından eserleri Türkçeye kazandırmamıştır?', 'Ahmed Arif', ['Can Yücel', 'Orhan Veli Kanık', 'Ataol Behramoğlu'], 'Can Yücel Shakespeare\'i, Orhan Veli La Fontaine\'i, Ataol Behramoğlu Rus yazarlarını çevirmiştir. Ahmed Arif çevirmenliğiyle tanınmaz.'),
  ('Aşağıdaki şair-meslek eşleştirmelerinden hangisi yanlıştır?', 'Behçet Necatigil – subay', ['Edip Cansever – antikacı', 'Cemal Süreya – maliye müfettişi', 'Oktay Rifat – avukat'], 'Behçet Necatigil edebiyat öğretmenidir. Diğer eşleştirmeler doğrudur.'),
  ('Aşağıdaki şiir topluluklarından hangisi ortak bir kitapla değil, bir dergi çevresinde ortaya çıkmıştır?', 'Hisar', ['Yedi Meşale', 'Garip', 'Beş Hececiler'], 'Hisarcılar 1950\'de çıkan Hisar dergisi çevresinde toplanmıştır. Yedi Meşale ve Garip ortak kitaplarla ortaya çıkmış; Beş Hececiler ise hece ölçüsünü benimseyen beş şaire sonradan verilmiş bir addır.'),
  ('Aşağıdaki eserlerden hangisi şiir kitabı değil, düzyazı türünde bir eserdir?', 'Şapkam Dolu Çiçekle', ['Sevda Sözleri', 'Yerçekimli Karanfil', 'Kınar Hanımın Denizleri'], 'Şapkam Dolu Çiçekle Cemal Süreya\'nın yazılarından oluşur; diğerleri şiir kitaplarıdır.'),
  ('1941-1950 yılları arasında Türk şiirinde en çok tartışılan ve genç şairler üzerinde en geniş etkiyi bırakan hareket hangisidir?', 'Garip', ['Hisar', 'İkinci Yeni', 'Yedi Meşale'], 'Garip 1941\'de ortaya çıkmış ve Orhan Veli\'nin öldüğü 1950\'ye kadar şiir ortamının merkezinde yer almıştır.'),
  ('1960-1980 arasında Türk şiirinde güç kazanan iki ana eğilim hangi seçenekte doğru verilmiştir?', 'Toplumcu şiir ve İslami duyarlılıklı şiir', ['Beş Hececiler\'in memleket şiiri ve Yedi Meşale şiiri', 'Garip\'in ilk dönem şiiri ve divan şiiri', 'Fecr-i Âti şiiri ve Servet-i Fünun şiiri'], '1961 sonrası ortamda toplumcu şiir yeniden yükselmiş, aynı dönemde Diriliş, Edebiyat ve Mavera çevresinde İslami duyarlılıklı şiir de gelişmiştir.'),
  ('Aşağıdakilerden hangisi şehir hayatını ve şehirli insanın yalnızlığını şiirlerinde öne çıkaran şairleri bir arada verir?', 'Necip Fazıl, Turgut Uyar, Attila İlhan', ['Kemalettin Kamu, Ömer Bedrettin Uşaklı, Cahit Külebi', 'Ahmed Arif, Enver Gökçe, Hasan Hüseyin', 'Arif Nihat Asya, Behçet Kemal Çağlar, Faruk Nafiz'], 'Kaldırımlar, Her Pazartesi ve Sisler Bulvarı gibi eserler şehirli yalnızlığını işler. Diğer gruplar Anadolu, toplumcu ya da millî coşku temalarına yakındır.'),
  ('Aşağıdakilerden hangisi ölüm temasını şiirlerinin merkezine alan şairleri bir arada verir?', 'Cahit Sıtkı Tarancı, Necip Fazıl, Ziya Osman Saba', ['Orhan Veli, Oktay Rifat, Melih Cevdet', 'Ataol Behramoğlu, Can Yücel, Gülten Akın, Hilmi Yavuz', 'Faruk Nafiz, Enis Behiç, Yusuf Ziya'], 'Ölüm korkusu ve ölüm düşüncesi Cahit Sıtkı, Necip Fazıl ve Ziya Osman\'ın şiirlerinde belirleyici bir yer tutar.'),
  ('Cumhuriyet dönemi şiirinde \'birey\'in giderek öne çıkması hangi gelişmeyle birlikte değerlendirilebilir?', 'Millî ve toplumsal ülkülerin yanında kişinin iç dünyasına, kaygılarına yönelen modern bir duyarlılığın gelişmesi', ['Şiirin yalnızca padişah ve devlet büyüklerine yazılan övgülere ayrılması', 'Şiirin tümüyle ortadan kalkıp yerini mektuba bırakması', 'Şiirin yalnızca dinî törenlerde okunur hâle gelmesi'], 'Saf şiirden Garip\'e, İkinci Yeni\'den 1980 sonrasına kadar bireyin iç dünyası, yalnızlığı ve kaygıları şiirin temel konularından biri olmuştur.'),
  ('Cumhuriyet dönemi şiirinde \'savaş ve barış\' temasının işlenişine örnek olarak hangisi verilebilir?', 'Nazım Hikmet\'in Hiroşima\'yı anlatan \'Kız Çocuğu\' şiiri ve Dağlarca\'nın \'Vietnam Savaşımız\' kitabı', ['Yahya Kemal\'in \'Sessiz Gemi\' şiiri ve Dıranas\'ın \'Olvido\' şiiri', 'Orhan Veli\'nin \'Bedava\' şiiri ve Özdemir Asaf\'ın \'Lavinia\' şiiri', 'Necatigil\'in \'Evler\' kitabı ve Külebi\'nin \'Süt\' kitabı'], 'Bu iki eser savaşın insan üzerindeki yıkımına karşı barış çağrısı yapar; diğer seçeneklerdeki eserler ölüm, aşk ya da gündelik hayat temalıdır.'),
  ('Bir edebiyat öğretmeni \'Garip\'ten İkinci Yeni\'ye geçiş\' konulu bir ders için iki şiir kitabı seçecek. Hangi çift bu geçişi en iyi gösterir?', 'Garip ve Üvercinka', ['Çile ve Sebil ve Güvercinler', 'Han Duvarları ve Çoban Çeşmesi', 'Kuvâyi Milliye ve Hasretinden Prangalar Eskittim'], 'Garip (1941) yalın şiirin, Üvercinka (1958) İkinci Yeni\'nin imgeci şiirinin temel kitabıdır; diğer çiftler aynı ya da farklı çizgilerdeki eserlerdir.'),
  ('Bir antoloji hazırlayan editör \'toplumcu gerçekçi şiir\' bölümüne üç şiir koymak istiyor. Hangi şair üçlüsünden seçim yapması en uygundur?', 'Nazım Hikmet, Ahmed Arif, Hasan Hüseyin Korkmazgil', ['Ahmet Muhip Dıranas, Ziya Osman Saba, Tanpınar', 'Ece Ayhan, İlhan Berk, Turgut Uyar', 'Mehmet Çınarlı, Yavuz Bülent Bakiler, Gültekin Samanoğlu'], 'Nazım, Ahmed Arif ve Hasan Hüseyin toplumcu gerçekçi şiirin önemli temsilcileridir; diğer gruplar saf şiir, İkinci Yeni ve Hisar çizgisindedir.'),
  ('Bir öğrenci, şiirde \'gelenekle modernliği buluşturma\' konusunu incelemek istiyor. Aşağıdaki şair çiftlerinden hangisi bu konu için en uygun örnektir?', 'Hilmi Yavuz ve Turgut Uyar (Divan dönemi)', ['Orhan Veli ve Rıfat Ilgaz', 'Ahmed Arif ve Enver Gökçe', 'Küçük İskender ve Nilgün Marmara (1980 kuşağı)'], 'Hilmi Yavuz\'un Doğu Şiirleri ve Turgut Uyar\'ın Divan\'ı, eski şiirin biçim ve imgelerini modern şiirde yeniden yorumlar.'),
  ('Bir müzisyen, halk türküsü havasında bestelenebilecek bir modern şiir arıyor. Aşağıdaki şairlerden hangisinin şiirleri bu amaca en uygundur?', 'Cahit Külebi', ['Ece Ayhan', 'İlhan Berk', 'Melih Cevdet Anday'], 'Külebi\'nin türkü söyleyişine yakın, ezgili şiirleri bestelenmeye elverişlidir; diğer seçenekler kapalı ya da düşünsel şiirlerdir.'),
  ('Bir öğrenci Cumhuriyet döneminde dinî ve metafizik duyarlılığın şiire yansımasını incelemek için kronolojik bir sıra kuruyor. Hangi sıralama doğrudur?', 'Necip Fazıl → Sezai Karakoç → Cahit Zarifoğlu', ['Cahit Zarifoğlu → Necip Fazıl → Sezai Karakoç', 'Sezai Karakoç → Cahit Zarifoğlu → Necip Fazıl', 'Cahit Zarifoğlu → Sezai Karakoç → Necip Fazıl'], 'Necip Fazıl 1920\'lerde, Sezai Karakoç 1950\'lerde, Cahit Zarifoğlu 1960\'larda şiire başlamıştır.'),
  ('Bir öğrenci \'kadın sesi\' teması üzerine bir sunum hazırlıyor ve farklı kuşaklardan üç kadın şair seçmek istiyor. Hangi seçim doğru ve uygundur?', 'Gülten Akın, Nilgün Marmara, Didem Madak', ['Gülten Akın, Ece Ayhan, Didem Madak', 'Nilgün Marmara, Özdemir Asaf, Birhan Keskin', 'Didem Madak, Ülkü Tamer, Gülten Akın'], 'Gülten Akın (1950\'ler), Nilgün Marmara (1980\'ler) ve Didem Madak (2000\'ler) farklı kuşaklardan kadın şairlerdir. Ece Ayhan, Özdemir Asaf ve Ülkü Tamer erkek şairlerdir.'),
  ('\'Seni düşünmek güzel şey, ümitli şey\' dizesiyle başlayan ve sevgiliyi umutla birlikte anan şiir hangi şaire aittir?', 'Nazım Hikmet', ['Ahmet Muhip Dıranas', 'Ahmed Arif', 'Cemal Süreya'], 'Bu dize Nazım Hikmet\'e aittir; şair sevgiliyi düşünmeyi dünyanın en güzel şarkısını dinlemeye benzetir.'),
  ('\'Ne güzel şey hatırlamak seni: / ölüm ve zafer haberleri içinden\' dizeleriyle savaş yıllarında sevgiliyi anan şair kimdir?', 'Nazım Hikmet', ['Fazıl Hüsnü Dağlarca', 'Sabahattin Ali', 'Oktay Rifat'], 'Dizeler Nazım Hikmet\'in hapisteyken yazdığı aşk şiirlerindendir; sevgili, savaşın ve acıların ortasında bir umut kaynağıdır.'),
  ('Arif Nihat Asya\'nın \'Bayrak Şairi\' olarak anılmasının nedeni hangisidir?', 'Bayrak ve vatan sevgisini coşkulu biçimde işleyen şiirleriyle tanınması', ['Bir bayrak fabrikasının sahibi olması', 'Türk bayrağının ölçülerini ve tasarımını belirleyen resmî kurulun başkanı olması', 'Yalnızca bayram günlerinde şiir yazması'], 'Arif Nihat Asya\'nın \'Bayrak\' şiiri başta olmak üzere millî coşkuyu dile getiren şiirleri ona bu unvanı kazandırmıştır.'),
  ('Neyzen Tevfik\'in şiir dışında asıl ününü kazandığı sanat alanı hangisidir?', 'Ney çalmak', ['Hat yazmak', 'Minyatür yapmak', 'Çini işlemek'], 'Neyzen adı, onun ney üstadı olmasından gelir; Neyzen Tevfik Türk musikisinin usta ney icracılarındandır.'),
  ('Cumhuriyet döneminde mizah ve hicivle tanınan şairler ile lirik şairler karşılaştırıldığında hangi sonuca ulaşılır?', 'Şiir, yalnız duygu dile getirmek için değil toplumu eleştirmek için de etkili bir araç olarak kullanılmıştır.', ['Mizahi şiir Cumhuriyet döneminde hiç yazılmamıştır.', 'Lirik şiir yasaklanmış, yalnız hiciv serbest bırakılmıştır.', 'Hiciv yalnızca aruzla, lirik şiir yalnızca heceyle yazılmıştır.'], 'Neyzen Tevfik, Yusuf Ziya Ortaç ve Can Yücel gibi isimler şiirin eleştiri ve mizah gücünü gösterirken lirik şairler duygu dünyasını işlemiştir.'),
  ('Orhan Veli hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Hisar dergisinin kurucuları arasında yer almıştır.', ['Yaprak adlı bir dergi çıkarmıştır.', 'La Fontaine\'den çeviriler yapmıştır.', 'Garip kitabının önsözünü kaleme alarak topluluğun görüşlerini açıklamıştır.'], 'Orhan Veli 1950\'de ölmüştür; Hisar o yıl Mehmet Çınarlı ve arkadaşlarınca kurulmuştur ve gelenekçi bir çizgide Garip\'e karşı çıkmıştır.'),
  ('Necip Fazıl hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'İkinci Yeni\'nin kuramcısı olarak Papirüs dergisini çıkarmıştır.', ['Büyük Doğu dergisini yayımlamış ve çevresinde bir fikir hareketi oluşturmuştur.', 'Tiyatro eserleri de yazmıştır.', 'Şiirlerinde hece ölçüsünü kullanmıştır.'], 'Papirüs Cemal Süreya\'nın dergisidir; Necip Fazıl İkinci Yeni\'nin kuramcısı değildir.'),
  ('Behçet Necatigil hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Garip\'in ortak kitabında şiirleri yayımlanmıştır.', ['Edebiyat öğretmenliği yapmıştır.', 'Radyo oyunları yazmıştır.', 'Almancadan Rilke ve Hesse gibi yazarların eserlerini Türkçeye çevirmiştir.'], 'Garip kitabında yalnızca Orhan Veli, Oktay Rifat ve Melih Cevdet\'in şiirleri vardır; Necatigil topluluk dışı bir şairdir.'),
  ('Cahit Sıtkı Tarancı hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Şiirlerini ölçüsüz ve kafiyesiz yazmayı ilke edinmiştir.', ['Diyarbakır\'da doğmuştur.', 'Otuz Beş Yaş ile 1946\'da bir şiir yarışmasını kazanmıştır.', 'Ölüm korkusunu sıkça işlemiştir.'], 'Cahit Sıtkı ölçü ve kafiyeye bağlı, biçime özen gösteren bir şairdir; ölçüsüz yazmayı ilke edinen Garip şairleridir.'),
  ('Sezai Karakoç hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Garip hareketinin ortak kitabında şiir yayımlamıştır.', ['Diriliş dergisini çıkarmıştır.', 'Şiirlerinde İslami bir medeniyet düşüncesini işlemiştir.', 'Mona Roza şiiriyle tanınmıştır.'], 'Sezai Karakoç 1933 doğumludur ve 1941\'de yayımlanan Garip\'le bir ilgisi yoktur; İkinci Yeni içinde değerlendirilir.'),
  ('Ahmed Arif hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Çok sayıda şiir kitabı yayımlayarak en üretken şairlerden biri olmuştur.', ['Diyarbakır\'da doğmuştur.', 'Otuz Üç Kurşun şiirini yazmıştır.', 'Leyla Erbil\'e yazdığı mektuplar ölümünden sonra kitap hâline getirilmiştir.'], 'Ahmed Arif\'in yayımlanmış tek şiir kitabı vardır: Hasretinden Prangalar Eskittim.'),
  ('Melih Cevdet Anday hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Hece ölçüsüyle memleket şiiri yazan Beş Hececiler\'den biridir.', ['Garip\'in üç şairinden biridir.', 'Şiirin yanında tiyatro oyunları, romanlar ve gazetelerde denemeler de yazmıştır.', 'Şiirinde mitolojiye ve düşünceye yönelmiştir.'], 'Beş Hececiler Faruk Nafiz, Enis Behiç, Halit Fahri, Orhan Seyfi ve Yusuf Ziya\'dır; Melih Cevdet Garip şairidir.'),
  ('Ece Ayhan hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Şiirlerinde açık ve kolay anlaşılır bir dil kullanmayı ilke edinmiştir.', ['Sivil şiir kavramını ortaya atmıştır.', 'Datça\'da doğmuştur.', 'Kınar Hanımın Denizleri adlı kitabı İkinci Yeni\'nin verimli yılı 1959\'da yayımlamıştır.'], 'Ece Ayhan İkinci Yeni\'nin en kapalı şairlerinden biridir; açık ve kolay bir dil onun şiirinin özelliği değildir.'),
  ('Fazıl Hüsnü Dağlarca hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'İkinci Yeni\'ye adını veren yazıyı Pazar Postası\'nda yayımlamıştır.', ['Subay olarak çalışmıştır.', 'Çocuk ve Allah adlı kitabı yazmıştır.', 'Kurtuluş Savaşı\'nı ve Çanakkale\'yi destan havasında işleyen kitaplar yazmıştır.'], 'İkinci Yeni adını kullanan Muzaffer İlhan Erdost\'tur; Dağlarca bir topluluğa bağlanmamış bağımsız bir şairdir.'),
  ('Gülten Akın hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Yedi Meşale topluluğunun kurucuları arasında yer almıştır.', ['İlk kitabı Rüzgâr Saati\'dir.', 'Toplumsal konuları ağıt ve türkü biçimlerinden yararlanarak işleyen şiirler yazmıştır.', 'Kadın deneyimini şiirine taşımıştır.'], 'Yedi Meşale 1928\'de kurulmuştur; 1933 doğumlu Gülten Akın\'ın bu toplulukla ilgisi yoktur.'),
  ('Edip Cansever hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Hisar dergisinin gelenekçi çizgisini savunan kurucularındandır.', ['Kapalıçarşı\'da antikacılık yapmıştır.', 'Şiirlerinde kişileri konuşturarak tiyatroya yaklaşan dramatik bir yapı kullanmıştır.', 'Yerçekimli Karanfil kitabını yayımlamıştır.'], 'Edip Cansever İkinci Yeni\'nin önemli şairlerindendir; Hisar\'ın kurucuları arasında yer almaz.'),
  ('Can Yücel hakkında verilen aşağıdaki bilgilerden hangisi yanlıştır?', 'Şiirlerinde ağır Osmanlıca tamlamalar kullanıp argodan özenle kaçınmıştır.', ['Hasan Âli Yücel\'in oğludur.', 'Shakespeare\'in oyunlarını ve sonelerini kendine özgü bir dille Türkçeye çevirmiştir.', 'Datça\'da yaşamıştır.'], 'Can Yücel argo ve gündelik dili şiirine rahatça sokan, mizahı seven bir şairdir.'),
  ('Hayranları ve izleyicileri arasında \'Üstad\' unvanıyla anılan şair kimdir?', 'Necip Fazıl Kısakürek', ['Orhan Veli Kanık', 'Ahmet Muhip Dıranas', 'Attila İlhan'], 'Necip Fazıl, Büyük Doğu çevresinde ve sonraki kuşaklar arasında \'Üstad\' diye anılmıştır.'),
  ('Cumhuriyet döneminde ortaya çıkan şiir topluluklarının çoğunun kısa ömürlü olmasının en önemli nedeni hangisidir?', 'Üyelerin zamanla kendi kişisel seslerini bulup farklı yollara ayrılması', ['Devletin her topluluğu kuruluşundan hemen sonra yasaklaması', 'Okurların şiir okumayı tamamen bırakması', 'Bütün toplulukların aynı kişi tarafından yönetilmesi'], 'Yedi Meşale ve Garip gibi topluluklarda üyeler bir süre sonra bireysel çizgilerine yönelmiş, ortak ilkeler kalıcı olmamıştır.'),
  ('Bir şiir topluluğunun ortak kitabına yazılan önsöz (Yedi Meşale ve Garip örneklerinde olduğu gibi) hangi işlevi görür?', 'Topluluğun şiir anlayışını ve karşı çıktığı şeyleri okura duyurmak', ['Kitabın satış fiyatını ve dağıtım yerlerini bildirmek', 'Şairlerin doğum tarihlerini, adreslerini ve aile bilgilerini okura vermek', 'Kitaptaki şiirlerin nota yazımını göstermek'], 'Önsözler toplulukların bildirisi işlevi görmüş; yeni şiirin ilkelerini ve neye tepki olduğunu açıklamıştır.'),
  ('Toplumcu şiire \'gerçekçi\' sıfatının eklenmesinin nedeni hangisidir?', 'Toplumsal gerçekliği, özellikle emekçilerin yaşam koşullarını olduğu gibi yansıtma iddiası taşıması', ['Şiirlerin yalnızca gerçek kişilerin adlarını kullanması', 'Şiirlerin bilimsel deneylere ve laboratuvar ölçümlerine dayanarak yazılması', 'Şiirlerin hayal ürünü hiçbir öğe içermemesi'], 'Toplumcu gerçekçilik, sanatın toplumsal gerçekliği ve sınıf ilişkilerini yansıtması gerektiğini savunur.'),
  ('Cumhuriyet döneminde çıkan dergilerin ve hareketlerin adlarında \'yeni\' sözcüğünün sık kullanılması (Yeni Adam, Yeni Ufuklar, Yeni Dergi, İkinci Yeni gibi) neyi gösterir?', 'Edebiyat ortamında sürekli bir yenilenme ve değişim isteğinin bulunduğunu', ['Bütün bu yayınların aynı kişi tarafından çıkarıldığını', 'Eski edebiyatın tamamen yasaklandığını', 'Dergilerin yalnızca yeni basılmış kitapların reklamını yaptığını'], 'Bu adlar, Cumhuriyet\'in kültür hayatında yeni bir şey söyleme ve öncekinden ayrılma isteğinin göstergesidir.'),
  ('1940\'larda saf şiir çizgisindeki şairlerle Garip şairlerinin aynı anda ürün vermesi, dönemin şiir ortamı hakkında ne söyler?', 'Tek bir anlayışın değil, birbirine karşıt anlayışların yan yana yaşadığı çoğulcu bir ortam bulunduğunu', ['Bütün şairlerin aynı ilkelere bağlı olduğunu', 'Şiirin yalnızca devlet eliyle yazıldığını', 'O yıllarda hiç şiir kitabı yayımlanmadığını ve dergilerin kapandığını'], 'Ahenkçi ve ölçülü saf şiir ile ölçüsüz, gündelik Garip şiiri aynı yıllarda okurla buluşmuştur.'),
  ('Cumhuriyet dönemi şiirinde \'Kurtuluş Savaşı\' konusunu işleyen eserler arasında hangisi yer almaz?', 'Umutsuzlar Parkı', ['Kuvâyi Milliye', 'Üç Şehitler Destanı', 'Atatürk Kurtuluş Savaşında'], 'Umutsuzlar Parkı Edip Cansever\'in varoluşçu bir şiir kitabıdır; diğerleri Millî Mücadele\'yi konu alır.'),
  ('Aşağıdaki şiir kitaplarından hangisinin adı bir mekânı değil, bir duyguyu ya da durumu anlatır?', 'Elde Var Hüzün', ['Kapalıçarşı', 'Galile Denizi', 'Umutsuzlar Parkı'], 'Elde Var Hüzün bir ruh hâlini anlatır; Kapalıçarşı, Galile Denizi ve Umutsuzlar Parkı ise birer mekân adıdır.'),
  ('Cumhuriyet dönemi şairlerinin pek çoğunun aynı zamanda çevirmen olması Türk şiirine en çok hangi katkıyı sağlamıştır?', 'Dünya şiirinin biçim ve duyarlılıklarını Türkçeye taşıyıp şiir dilini zenginleştirme', ['Türk şiirini tamamen yabancı dillere çevirip Türkçeyi bırakma', 'Divan şiirini yasaklayıp yerine yalnız çeviri okutma', 'Şairlerin kendi şiir yazmayı bütünüyle bırakması'], 'Orhan Veli, Can Yücel, Ataol Behramoğlu, Behçet Necatigil gibi çevirmen şairler Türk şiirine yeni ufuklar açmıştır.'),
];
